window.__Q=window.__Q||{};window.__Q["prev/8/B1"]=[{"q":"40岁男性，夜间突发左侧腰疼，伴有尿频、血尿，最主要的查体部位是","o":["肋弓下缘","髂前上棘","肋脊角","耻骨联合","剑突"],"a":2,"e":"肋脊角为第12肋骨与脊柱的交角，是检查肾脏压、叩痛的部位，肾盂肾炎、肾结石等肾区病变在此有叩击痛。髂前上棘为九区分法及骨髓穿刺体表标志，并非肾区查体点；耻骨联合是腹部体表下界；剑突为胸骨下端，均与肾脏叩痛无关"},{"q":"30岁女性，出现转移性右下腹痛，其查体体表定位标志之一是","o":["肋弓下缘","髂前上棘","肋脊角","耻骨联合","剑突"],"a":1,"e":"转移性右下腹痛是急性阑尾炎的典型表现，麦氏点位于髂前上棘与脐连线的中外1/3处，故髂前上棘是其体表定位标志之一。肋脊角用于肾脏叩痛检查；耻骨联合为腹部下界标志；肋弓下缘参与九区分法水平线，均不用于阑尾压痛点定位"},{"q":"多在发热或呼吸道感染后突然出现眩晕，伴恶心、呕吐，一般无耳鸣及听力减退","o":["梅尼埃病","迷路炎","前庭神经元炎","位置性眩晕","晕动病"],"a":2,"e":"前庭神经元炎多在发热或上呼吸道感染后突然起病，表现为眩晕伴恶心、呕吐，因病变在前庭神经而一般无耳鸣及听力减退，持续时间较长且少复发。梅尼埃病以反复发作眩晕伴耳鸣、波动性听力减退为特征；迷路炎多继发中耳炎并有鼓膜穿孔；位置性眩晕由特定头位诱发"},{"q":"多由中耳炎并发，以发作性眩晕伴耳鸣、听力减退及眼球震颤为主要特点，检查发现鼓膜穿孔","o":["梅尼埃病","迷路炎","前庭神经元炎","位置性眩晕","晕动病"],"a":1,"e":"迷路炎多由中耳炎并发，炎症累及内耳迷路，故有发作性眩晕、耳鸣、听力减退及眼球震颤，查体可见鼓膜穿孔。梅尼埃病虽也发作性眩晕伴耳鸣听力下降，但无中耳炎史及鼓膜穿孔，听力呈波动性；前庭神经元炎无耳鸣与听力减退；晕动病由运动刺激诱发，无耳部器质性体征"},{"q":"表现为中毒性呼吸困难的是","o":["支气管哮喘","气道阻塞","重症肺炎","糖尿病酮症","癔症"],"a":3,"e":"糖尿病酮症等代谢性酸中毒时血中酸性代谢产物增多，刺激颈动脉窦、主动脉体化学感受器或呼吸中枢，出现深大呼吸，属中毒性呼吸困难。重症肺炎因肺换气面积减少表现为混合性呼吸困难；支气管哮喘为呼气性；气道阻塞为吸气性；癔症多为过度通气所致的功能性呼吸异常"},{"q":"表现为呼气性呼吸困难的是","o":["支气管哮喘","气道阻塞","重症肺炎","糖尿病酮症","癔症"],"a":0,"e":"支气管哮喘等下呼吸道阻塞时气流呼出不畅，呼气用力且时间延长，故表现为呼气性呼吸困难，常伴哮鸣音。气道阻塞如气管异物为吸气性呼吸困难，吸气时间延长；重症肺炎因换气面积减少呈混合性；糖尿病酮症为中毒性深大呼吸；癔症为精神因素所致功能性呼吸异常"},{"q":"表现为吸气性呼吸困难的是","o":["支气管哮喘","气道阻塞","重症肺炎","糖尿病酮症","癔症"],"a":1,"e":"喉、气管等上气道阻塞时吸气困难、吸气时间延长，故气道阻塞表现为吸气性呼吸困难，重者有三凹征。支气管哮喘为呼气性呼吸困难；重症肺炎呈混合性；糖尿病酮症为中毒性呼吸困难；癔症属精神因素所致功能性呼吸异常，无气道器质性阻塞"},{"q":"表现为混合性呼吸困难的是","o":["支气管哮喘","气道阻塞","重症肺炎","糖尿病酮症","癔症"],"a":2,"e":"重症肺炎、大量胸腔积液、气胸等使肺或胸膜腔病变导致呼吸面积减少、换气障碍，吸气与呼气均费力，故表现为混合性呼吸困难。支气管哮喘为呼气性；气道阻塞为吸气性；糖尿病酮症属中毒性；癔症为功能性，均无肺换气面积减少的病理基础"},{"q":"病态窦房结综合征引起心悸的原因是","o":["心脏搏动增强","自主神经功能紊乱","心力衰竭","β受体功能亢进","心律失常"],"a":4,"e":"病态窦房结综合征因窦房结及周围组织退行性病变，产生重度窦性心动过缓、窦性停搏等缓慢性心律失常，心悸源于心律失常。心脏搏动增强见于高血压心脏病等心室肥厚；自主神经功能紊乱见于心脏神经症；β受体功能亢进属功能性；心力衰竭与心功能减退相关，均非本病机制"},{"q":"高血压心脏病引起心悸的原因是","o":["心脏搏动增强","自主神经功能紊乱","心力衰竭","β受体功能亢进","心律失常"],"a":0,"e":"高血压心脏病因长期压力负荷致左心室肥大、心肌收缩力增强、心搏出量增加，心脏搏动增强而产生心悸。心律失常见于病态窦房结综合征等；自主神经功能紊乱为心脏神经症机制；β受体功能亢进属功能性心悸；心力衰竭时心肌收缩力反而减弱，不以搏动增强为特征"},{"q":"心脏神经官能综合征引起心悸的原因是","o":["心脏搏动增强","自主神经功能紊乱","心力衰竭","β受体功能亢进","心律失常"],"a":1,"e":"心脏神经症由自主神经功能紊乱引起，心脏本身无器质性病变，多在焦虑、紧张、情绪激动时发生心悸，伴心率加快及神经衰弱表现。心脏搏动增强见于高血压心脏病；心律失常见于病态窦房结综合征；β受体功能亢进为功能性高动力状态；心力衰竭有器质性心脏病基础，均与本症不同"},{"q":"败血症","o":["稽留热","弛张热","间歇热","波状热","不规则热"],"a":1,"e":"弛张热又称败血症热型，体温常在39℃以上，24小时内波动范围超过2℃，但最低仍高于正常，败血症为其典型病因。稽留热24小时波动不超过1℃，见于大叶性肺炎；间歇热体温骤降后无热期与高热期交替，见于疟疾；波状热见于布鲁菌病；不规则热无规律，见于支气管肺炎"},{"q":"支气管肺炎","o":["稽留热","弛张热","间歇热","波状热","不规则热"],"a":4,"e":"不规则热的体温曲线无一定规律，可见于支气管肺炎、结核病、风湿热、渗出性胸膜炎等。稽留热持续高热且波动小，见于大叶性肺炎；弛张热波动大但不降至正常，为败血症热型；间歇热见于疟疾；波状热见于布鲁菌病，均具特定规律"},{"q":"布鲁菌病","o":["稽留热","弛张热","间歇热","波状热","不规则热"],"a":3,"e":"波状热体温逐渐升至39℃以上，数天后又渐降至正常，反复多次呈波浪状，是布鲁菌病的特征热型。稽留热波动小，见于大叶性肺炎；弛张热波动大但不降至正常，见于败血症；间歇热骤升骤降伴无热期，见于疟疾；不规则热无规律，见于支气管肺炎"},{"q":"大叶性肺炎","o":["稽留热","弛张热","间歇热","波状热","不规则热"],"a":0,"e":"稽留热体温恒定维持于39～40℃以上达数天或数周，24小时波动不超过1℃，大叶性肺炎高热期为其典型。弛张热波动超过2℃且最低仍高于正常，见于败血症；间歇热伴无热期，见于疟疾；波状热渐升渐降，见于布鲁菌病；不规则热无规律，见于支气管肺炎"},{"q":"随蛋白C活化而增高的是","o":["vWF","TM","FPA","PCP","6-酮-PGF1a"],"a":3,"e":"在凝血酶与凝血酶调节蛋白复合物作用下，蛋白C被活化为活化蛋白C，随蛋白C活化而增高。FPA随纤维蛋白生成而增多，反映凝血酶活性；TM增高提示内皮抗凝作用增强；vWF在各种血栓病中增高，示内皮损伤；6-酮-PGF1α为内皮抗凝指标，血管损伤时反降低"},{"q":"血栓病中可见增高的是","o":["vWF","TM","FPA","PCP","6-酮-PGF1a"],"a":0,"e":"vWF由内皮细胞合成，是介导血小板黏附的因子，在各种血栓性疾病中均增高，故可用于血栓病的判断。TM虽也增高但反映内皮抗凝作用；FPA随纤维蛋白生成增多；6-酮-PGF1α血管损伤时降低；蛋白C随活化增高，均非各种血栓病普遍增高的内皮损伤标志"},{"q":"血管受损时降低的是","o":["vWF","TM","FPA","PCP","6-酮-PGF1a"],"a":4,"e":"6-酮-前列腺素F1α由血管内皮细胞合成，通过抗血小板聚集和扩张血管发挥抗凝作用，血管受损时其合成减少而降低。vWF与内皮素为内皮促凝物质，血管损伤时增高；TM为内皮抗凝蛋白，损伤时也增高；FPA随纤维蛋白生成而增多，均不随血管受损而降低"},{"q":"随纤维蛋白生成而增多的是","o":["vWF","TM","FPA","PCP","6-酮-PGF1a"],"a":2,"e":"凝血酶作用于纤维蛋白原，使其先后丢失纤维蛋白肽A和肽B，FPA随纤维蛋白生成而增多，是凝血酶生成的敏感特异标志。vWF在各种血栓病中增高；TM增高反映内皮抗凝增强；6-酮-PGF1α血管损伤时降低；蛋白C随活化增高，均与纤维蛋白生成无直接对应"},{"q":"颈椎病（神经根型）可出现","o":["压颈试验阳性","拾物试验阳性","直腿抬高试验阳性","“4”字试验阳性","骨神经牵拉实验阳性"],"a":0,"e":"压颈试验（颈静脉加压试验）压迫颈静脉使脑脊液回流受阻、蛛网膜下腔压力增高，神经根型颈椎病患者颈部及上肢疼痛加重，故阳性。拾物试验阳性见于腰椎病变；直腿抬高试验用于坐骨神经及腰椎间盘病变；“4”字试验用于骶髂关节病变，均非颈椎病体征"},{"q":"脊柱结核可出现","o":["压颈试验阳性","拾物试验阳性","直腿抬高试验阳性","“4”字试验阳性","骨神经牵拉实验阳性"],"a":1,"e":"拾物试验要求患者保持腰部挺直蹲下取物，腰椎病变时不能弯腰而呈阳性，脊柱结核破坏椎体故可出现。压颈试验用于神经根型颈椎病；直腿抬高试验提示坐骨神经受牵拉；“4”字试验检查骶髂关节，均与腰椎结核的拾物姿势无关"},{"q":"大叶性肺炎患者痰液呈","o":["粉红色泡沫样痰","铁锈色痰","黏液性痰","黄绿色脓性痰","棕褐色痰"],"a":1,"e":"铁锈色痰是肺炎链球菌所致大叶性肺炎的特征，因肺泡内红细胞破坏后含铁血黄素混入痰液而成。粉红色泡沫痰见于急性肺水肿；黄绿色痰提示铜绿假单胞菌感染；棕褐色痰多见于阿米巴肺脓肿；黏液性痰见于急性支气管炎及支气管哮喘，均非肺炎球菌肺炎特征"},{"q":"急性肺水肿患者痰液呈","o":["粉红色泡沫样痰","铁锈色痰","黏液性痰","黄绿色脓性痰","棕褐色痰"],"a":0,"e":"急性肺水肿时肺毛细血管压力骤升，液体及红细胞渗入肺泡，咯大量粉红色泡沫样痰，为急性左心衰竭的特征。铁锈色痰见于大叶性肺炎；黄绿色痰提示铜绿假单胞菌感染；棕褐色痰见于阿米巴肺脓肿；黏液性痰见于支气管炎与哮喘，均非肺水肿表现"},{"q":"支气管哮喘患者痰液呈","o":["粉红色泡沫样痰","铁锈色痰","黏液性痰","黄绿色脓性痰","棕褐色痰"],"a":2,"e":"黏液性痰黏稠、无色透明或灰白色，见于急性支气管炎、支气管哮喘及大叶性肺炎初期。粉红色泡沫痰为急性肺水肿特征；铁锈色痰为肺炎球菌肺炎特征；黄绿色脓性痰提示铜绿假单胞菌感染；棕褐色痰多见于阿米巴肺脓肿，均与哮喘的黏液性痰不同"},{"q":"升主动脉瘤的心尖搏动为","o":["胸骨左缘第5肋间锁骨中线内侧搏动","负性心尖冲动","抬举性搏动","剑突下搏动","胸骨右缘第二肋间搏动"],"a":4,"e":"升主动脉瘤或升主动脉扩张时，胸骨右缘第2肋间（主动脉瓣区）可出现收缩期搏动。胸骨左缘第5肋间锁骨中线内侧为正常心尖搏动位置；负性心尖搏动见于粘连性心包炎；抬举性搏动提示左心室肥厚；剑突下搏动多见于右心室增大或腹主动脉搏动，均非升主动脉瘤体征"},{"q":"粘连性心包炎的心尖搏动为","o":["胸骨左缘第5肋间锁骨中线内侧搏动","负性心尖冲动","抬举性搏动","剑突下搏动","胸骨右缘第二肋间搏动"],"a":1,"e":"负性心尖搏动指心脏收缩时心尖部胸壁反而内陷，见于粘连性心包炎或心包与周围组织广泛粘连。胸骨左缘第5肋间搏动为正常心尖搏动；抬举性搏动见于左心室肥厚；剑突下搏动见于右心室增大；胸骨右缘第2肋间搏动为升主动脉瘤或主动脉扩张表现，均不同"},{"q":"正常心脏的心尖搏动为","o":["胸骨左缘第5肋间锁骨中线内侧搏动","负性心尖冲动","抬举性搏动","剑突下搏动","胸骨右缘第二肋间搏动"],"a":0,"e":"正常成人心尖搏动位于第5肋间、左锁骨中线内侧0.5～1.0cm，范围直径2.0～2.5cm。负性心尖搏动为粘连性心包炎的收缩期内陷；抬举性搏动提示左室肥厚；剑突下搏动与右室增大或腹主动脉有关；胸骨右缘第2肋间搏动见于升主动脉瘤，均属异常搏动"},{"q":"免疫性血小板减少性紫癜可出现","o":["BT及PT都正常","BT延长，PT减少","BT延长，PT增多","BT延长，PT正常","BT正常，PT延长"],"a":1,"e":"免疫性血小板减少性紫癜因免疫性破坏致外周血小板显著减少，出血时间随之延长，这是血小板数量减少的直接后果。出血时间正常而血小板正常项见于过敏性紫癜等血管性紫癜，出血时间延长而血小板增多项见于血小板增多症，出血时间延长而血小板正常项见于血小板无力症等"},{"q":"血管性血友病可出现","o":["BT及PT都正常","BT延长，PT减少","BT延长，PT增多","BT延长，PT正常","BT正常，PT延长"],"a":3,"e":"血管性血友病因vWF缺陷致血小板黏附障碍，出血时间延长，而凝血酶原时间正常。过敏性紫癜为血管壁通透性增加，BT与PT均正常；BT延长、PLT减少见于原发免疫性血小板减少症；BT延长、PLT增多见于血小板增多症；PT延长提示外源性凝血途径缺陷，均非vWD表现"},{"q":"过敏性紫癜可出现","o":["BT及PT都正常","BT延长，PT减少","BT延长，PT增多","BT延长，PT正常","BT正常，PT延长"],"a":0,"e":"过敏性紫癜属血管壁通透性与脆性增加所致血管性紫癜，血小板及凝血因子均正常，故BT及PT都正常。血管性血友病因vWF缺陷致BT延长、PT正常；原发免疫性血小板减少症BT延长而血小板减少；凝血因子Ⅶ缺乏等外源性途径缺陷则PT延长而APTT正常，均与本病不同"},{"q":"Gordon征检查方法","o":["应用竹签沿患者足底外侧缘由后向前至小趾近足根部并转向内侧","检查者弯曲示指和中指，沿患者胫骨前缘用力由上向下滑压","检查者用手抬举患者头部，感受患者颈部抵抗力量","检查者用叩诊锤叩击髌韧带观察小腿活动","检查者用手以一定力量捏压腓肠肌"],"a":4,"e":"Gordon征检查者用手以一定力量捏压腓肠肌，阳性表现为踇趾背伸、余趾扇形展开，同Babinski征。Babinski征用竹签划足底外侧；Oppenheim征沿胫骨前缘由上向下滑压；抬举头部感受颈抵抗为颈强直检查；叩击髌韧带观察小腿活动为膝反射，均非Gordon征手法"},{"q":"Babinski征检查方法","o":["应用竹签沿患者足底外侧缘由后向前至小趾近足根部并转向内侧","检查者弯曲示指和中指，沿患者胫骨前缘用力由上向下滑压","检查者用手抬举患者头部，感受患者颈部抵抗力量","检查者用叩诊锤叩击髌韧带观察小腿活动","检查者用手以一定力量捏压腓肠肌"],"a":0,"e":"Babinski征用竹签沿足底外侧缘由后向前至小趾近足根部再转向内侧，阳性为踇趾背伸、余趾扇形展开，提示锥体束损害。Oppenheim征沿胫骨前缘由上下滑压；Gordon征捏压腓肠肌；颈强直检查抬举头部感受抵抗；叩击髌韧带为膝反射，手法各异"},{"q":"Oppenheim征检查方法","o":["应用竹签沿患者足底外侧缘由后向前至小趾近足根部并转向内侧","检查者弯曲示指和中指，沿患者胫骨前缘用力由上向下滑压","检查者用手抬举患者头部，感受患者颈部抵抗力量","检查者用叩诊锤叩击髌韧带观察小腿活动","检查者用手以一定力量捏压腓肠肌"],"a":1,"e":"Oppenheim征检查者弯曲示指和中指沿胫骨前缘用力由上向下滑压，阳性同Babinski征，提示锥体束受损。Babinski征用竹签划足底外侧缘；Gordon征捏压腓肠肌；抬举头部感受颈部抵抗为脑膜刺激征检查；叩击髌韧带观察小腿活动为膝反射，手法与部位均不同"},{"q":"婚姻史包括","o":["主要症状的特点","药物食物过敏史","出生地及居住时间","夫妻关系","生育次数"],"a":3,"e":"婚姻史包括婚姻状况、结婚年龄、配偶健康状况、性生活情况及夫妻关系。主要症状的特点属现病史；药物食物过敏史归既往史；出生地及居住时间属个人史；生育次数属生育史，均不属婚姻史范畴"},{"q":"既往史包括","o":["主要症状的特点","药物食物过敏史","出生地及居住时间","夫妻关系","生育次数"],"a":1,"e":"既往史包括既往健康状况、曾患疾病、外伤手术、预防接种及食物或药物过敏史等。主要症状特点属现病史；出生地及居住时间属个人史；夫妻关系属婚姻史；生育次数属生育史，均与既往史内容不符"},{"q":"现病史包括","o":["主要症状的特点","药物食物过敏史","出生地及居住时间","夫妻关系","生育次数"],"a":0,"e":"现病史是病史主体，记录疾病发生、发展、演变和诊治全过程，包含主要症状的特点即部位、性质、持续时间、程度及缓解加剧因素。药物食物过敏史属既往史；出生地及居住时间属个人史；夫妻关系属婚姻史；生育次数属生育史，均不在现病史之列"},{"q":"个人史包括","o":["主要症状的特点","药物食物过敏史","出生地及居住时间","夫妻关系","生育次数"],"a":2,"e":"个人史记录出生地及长期居留地、生活习惯、烟酒嗜好、职业与毒物接触史等，出生地及居住时间属其社会经历。主要症状特点属现病史；药物食物过敏史属既往史；夫妻关系属婚姻史；生育次数属生育史"},{"q":"尿失禁伴大便失禁或便秘者，见于","o":["急性膀胱炎","神经源性膀胱","前列腺增生","糖尿病性膀胱","上运动神经元病变"],"a":1,"e":"尿失禁伴大便失禁或便秘等排便功能紊乱，提示神经源性膀胱，因排尿与排便的神经支配共同受损。急性膀胱炎伴膀胱刺激征及脓尿；前列腺增生为50岁以上男性进行性排尿困难；上运动神经元病变多有肢体痉挛等，均不以伴排便紊乱为特征"},{"q":"50岁以上男性，尿失禁伴进行性排尿困难，见于","o":["急性膀胱炎","神经源性膀胱","前列腺增生","糖尿病性膀胱","上运动神经元病变"],"a":2,"e":"50岁以上男性出现尿失禁伴进行性排尿困难、尿线变细，是前列腺增生的典型表现，因增生的前列腺压迫尿道所致。急性膀胱炎伴膀胱刺激征与脓尿；神经源性膀胱伴排便功能紊乱；上运动神经元病变有神经系统体征；糖尿病性膀胱为感觉障碍性排尿困难，均不同"},{"q":"患者，女，32岁。乏力、手抖1年，心悸、胸闷1个月。查体：T 36.0℃，P 101次/min，R 21次/min，BP 138/62mmHg，甲状腺Ⅱ度肿大。该患者最可能的诊断是","o":["甲状腺功能亢进症","甲状腺功能减退症","单纯性甲状腺肿","桥本甲状腺炎","甲状腺癌"],"a":0,"e":"乏力、手抖、心悸、胸闷伴甲状腺Ⅱ度肿大，符合甲状腺功能亢进症，因甲状腺激素过多致代谢亢进与交感兴奋。甲状腺功能减退症表现为乏力、黏液性水肿、畏寒；单纯性甲状腺肿仅有甲状腺肿大而无高代谢症状；桥本甲状腺炎多伴甲状腺功能减低；甲状腺癌以结节为主"},{"q":"患者，女，25岁，乏力、颜面水肿半年就诊。查体：T 36.0℃，P 69次/min，R 21次/min，BP 120/62mmHg，甲状腺不大。该患者最可能的诊断是","o":["甲状腺功能亢进症","甲状腺功能减退症","单纯性甲状腺肿","桥本甲状腺炎","甲状腺癌"],"a":1,"e":"乏力、颜面水肿而甲状腺不大，符合甲状腺功能减退症，因黏液性水肿致颜面浮肿、面色苍黄、反应迟钝。甲状腺功能亢进症有畏热多汗、手抖、突眼及甲状腺肿大；单纯性甲状腺肿仅腺体肿大；桥本甲状腺炎早期可正常后期减低；甲状腺癌以局部结节为著，均不符"},{"q":"前列腺增生可见","o":["尿频、尿急伴有血尿，午后低热，乏力盗汗","尿频、尿急伴无痛性血尿","尿频、尿急和尿痛伴有尿流突然中断","尿频伴多饮、多尿和口渴，但无尿急和尿痛","老年男性尿频伴有尿线细，进行性排尿困难"],"a":4,"e":"老年男性尿频伴尿线细、进行性排尿困难是前列腺增生的特征，因增生腺体压迫后尿道致排尿阻力增加。尿频尿急伴血尿、午后低热盗汗提示泌尿系结核；无痛性血尿见于膀胱癌；尿流突然中断见于膀胱结石；多饮多尿口渴见于糖尿病或尿崩症，均非本病"},{"q":"膀胱癌可见","o":["尿频、尿急伴有血尿，午后低热，乏力盗汗","尿频、尿急伴无痛性血尿","尿频、尿急和尿痛伴有尿流突然中断","尿频伴多饮、多尿和口渴，但无尿急和尿痛","老年男性尿频伴有尿线细，进行性排尿困难"],"a":1,"e":"尿频、尿急伴无痛性血尿是膀胱癌的典型表现，肿瘤表面坏死出血且多无痛。伴血尿及午后低热、乏力盗汗提示泌尿系结核；尿流突然中断见于膀胱结石；多饮多尿口渴伴尿频见于糖尿病、尿崩症；老年男性尿线细、进行性排尿困难为前列腺增生，均不同"},{"q":"直肠指诊发现触及柔软、光滑富有弹性的包块","o":["肛裂","肛门直肠周围脓肿","直肠息肉","直肠癌","直肠炎症"],"a":2,"e":"直肠指诊触及柔软、光滑而富有弹性的包块，常为直肠息肉。直肠剧烈触痛多因肛裂及感染；触痛伴波动感见于肛门直肠周围脓肿；坚硬凹凸不平的包块提示直肠癌；指套带黏液血液多见于直肠炎症，均非息肉的质地特征"},{"q":"指诊后指套表面带有黏液及少量血液","o":["肛裂","肛门直肠周围脓肿","直肠息肉","直肠癌","直肠炎症"],"a":4,"e":"指诊后指套表面带有黏液及少量血液，提示直肠炎症，因黏膜充血糜烂渗出。直肠息肉为柔软光滑有弹性包块；直肠癌为坚硬凹凸不平包块；肛裂以剧烈触痛为主；肛门直肠周围脓肿触痛伴波动感，均不以指套黏液血便为特征"},{"q":"直肠指诊触及坚硬凹凸不平的包块","o":["肛裂","肛门直肠周围脓肿","直肠息肉","直肠癌","直肠炎症"],"a":3,"e":"直肠指诊触及坚硬凹凸不平的包块，应考虑直肠癌，因癌肿浸润生长致质硬、表面凹凸。柔软光滑有弹性包块为直肠息肉；剧烈触痛见于肛裂；触痛伴波动感为肛门直肠周围脓肿；指套带黏液血液多提示直肠炎症，均与癌性肿块质地不符"},{"q":"每分钟静息通气量是指","o":["安静状态每分钟进入呼吸性细支气管及肺泡与气体交换的有效通气量","静息状态下每分钟呼出的气量","用力肺活量测定过程中，呼气流速最快时的瞬间流速","在F-V曲线上计算获得用力呼出肺活量25%～75%的平均流量","自主呼吸每分钟最大通气量"],"a":1,"e":"每分钟静息通气量指静息状态下每分钟呼出的气量，等于潮气容积乘以呼吸频率。肺泡通气量为进入呼吸性细支气管及肺泡参与气体交换的有效通气量，需扣除无效腔；最大呼气中段流量为用力呼出25%～75%的平均流量；最大呼气流量为呼气流速最快的瞬间值；最大通气量为自主呼吸每分钟最大值"},{"q":"最大呼气中段流量是指","o":["安静状态每分钟进入呼吸性细支气管及肺泡与气体交换的有效通气量","静息状态下每分钟呼出的气量","用力肺活量测定过程中，呼气流速最快时的瞬间流速","在F-V曲线上计算获得用力呼出肺活量25%～75%的平均流量","自主呼吸每分钟最大通气量"],"a":3,"e":"最大呼气中期流量（MMEF/MMF）根据用力肺活量曲线计算，为用力呼出肺活量25%～75%的平均流量，反映小气道阻塞。每分钟静息通气量为静息每分钟呼出气量；肺泡通气量为进入肺泡参与交换的有效通气量；最大呼气流量为呼气流速最快的瞬间流速；最大通气量为自主呼吸每分钟最大值"},{"q":"肺泡通气量是指","o":["安静状态每分钟进入呼吸性细支气管及肺泡与气体交换的有效通气量","静息状态下每分钟呼出的气量","用力肺活量测定过程中，呼气流速最快时的瞬间流速","在F-V曲线上计算获得用力呼出肺活量25%～75%的平均流量","自主呼吸每分钟最大通气量"],"a":0,"e":"肺泡通气量指安静状态下每分钟进入呼吸性细支气管及肺泡参与气体交换的有效通气量，等于（潮气容积－无效腔气量）乘以呼吸频率。每分钟静息通气量为静息每分钟呼出气量，未扣除无效腔；最大呼气中段流量为用力呼出25%～75%平均流量；最大呼气流量为最快瞬间流速"},{"q":"最大呼气流量是指","o":["安静状态每分钟进入呼吸性细支气管及肺泡与气体交换的有效通气量","静息状态下每分钟呼出的气量","用力肺活量测定过程中，呼气流速最快时的瞬间流速","在F-V曲线上计算获得用力呼出肺活量25%～75%的平均流量","自主呼吸每分钟最大通气量"],"a":2,"e":"最大呼气流量（PEF）指用力肺活量测定过程中呼气流速最快时的瞬间流速，又称峰值呼气流量，反映呼吸肌力量及气道阻塞。肺泡通气量为进入肺泡的有效通气量；每分钟静息通气量为静息每分钟呼出气量；最大呼气中段流量为用力呼出25%～75%平均流量；最大通气量为自主呼吸每分钟最大值"},{"q":"PVO（混合静脉血氧分压）是2","o":["判断缺氧及程度指标","反映肺换气功能指标","判断肺通气状态指标","反映组织缺氧指标","反映代谢因素改变指标"],"a":3,"e":"混合静脉血氧分压（PvO2）指物理溶解于混合静脉血中氧产生的压力，正常35～45mmHg，常作为反映组织缺氧程度的指标。PaO2用于判断机体缺氧及程度；肺泡-动脉血氧分压差反映肺换气功能；动脉血氧饱和度反映氧与血红蛋白结合程度；二氧化碳相关指标反映通气状态，均非组织缺氧指标"},{"q":"PaO是2","o":["判断缺氧及程度指标","反映肺换气功能指标","判断肺通气状态指标","反映组织缺氧指标","反映代谢因素改变指标"],"a":0,"e":"动脉血氧分压（PaO2）指物理溶解于动脉血中氧产生的压力，是判断机体是否缺氧及其程度的重要指标。混合静脉血氧分压反映组织缺氧程度；肺泡-动脉血氧分压差反映肺换气功能；动脉血氧饱和度反映氧与血红蛋白结合程度且可掩盖缺氧；酸碱指标反映代谢因素，均非PaO2职责"},{"q":"PC（A-a）O（肺泡-动脉血氧分压差）是2","o":["判断缺氧及程度指标","反映肺换气功能指标","判断肺通气状态指标","反映组织缺氧指标","反映代谢因素改变指标"],"a":1,"e":"肺泡气-动脉血氧分压差P（A-a）O2等于肺泡气氧分压减去动脉血氧分压，是反映肺换气功能的指标，较PaO2更敏感。PaO2用于判断缺氧及程度；混合静脉血氧分压反映组织缺氧；动脉血氧饱和度反映氧与血红蛋白结合程度；二氧化碳相关指标判断肺通气状态，均非换气功能指标"},{"q":"输尿管结石","o":["强迫俯卧位","强迫仰卧位","强迫坐位","强迫停立位","辗转体位"],"a":4,"e":"输尿管结石引发的肾绞痛使患者辗转反侧、坐卧不安，故呈辗转体位，也见于胆石症、胆道蛔虫症。强迫仰卧位见于急性腹膜炎，蜷曲双腿减轻腹肌紧张；强迫俯卧位见于脊柱疾病；强迫坐位见于急性心衰端坐呼吸；强迫停立位见于心绞痛，均不同"},{"q":"急性腹膜炎","o":["强迫俯卧位","强迫仰卧位","强迫坐位","强迫停立位","辗转体位"],"a":1,"e":"急性腹膜炎患者仰卧并蜷曲双腿，以减轻腹部肌肉紧张与疼痛，故为强迫仰卧位。强迫俯卧位可减轻脊背肌紧张，见于脊柱疾病；强迫坐位（端坐呼吸）见于急性心力衰竭；强迫停立位见于心绞痛；辗转体位见于胆石症、肾绞痛，均非腹膜炎体位"},{"q":"急性心力衰竭","o":["强迫俯卧位","强迫仰卧位","强迫坐位","强迫停立位","辗转体位"],"a":2,"e":"急性心力衰竭患者端坐于床沿、两手扶持床边，即强迫坐位（端坐呼吸），可增加肺通气量、减少回心血量而减轻心脏负担。强迫仰卧位见于急性腹膜炎；强迫俯卧位见于脊柱疾病；强迫停立位见于心绞痛；辗转体位见于胆石症、肾绞痛，均非心衰体位"},{"q":"急性胃肠穿孔时，可见","o":["腹壁紧张度增加","腹壁紧张度减低","肝颈静脉回流征阳性","Courvoisier征阳性","振水音"],"a":0,"e":"急性胃肠穿孔后胃肠内容物进入腹腔引起弥漫性腹膜炎，腹肌强烈痉挛，故腹壁紧张度增加，甚至呈板状腹。腹壁紧张度减低见于慢性消耗性疾病或大量放腹水后；肝颈静脉回流征阳性为右心衰竭表现；Courvoisier征阳性见于胰头癌；振水音提示幽门梗阻，均非穿孔体征"},{"q":"幽门梗阻时，可见","o":["腹壁紧张度增加","腹壁紧张度减低","肝颈静脉回流征阳性","Courvoisier征阳性","振水音"],"a":4,"e":"幽门梗阻时胃内大量液体与气体存留，清晨空腹或餐后6～8小时以上仍可查出振水音，是其特征性体征。腹壁紧张度增加见于急性腹膜炎；腹壁紧张度减低见于大量放腹水后；肝颈静脉回流征阳性为右心衰竭；Courvoisier征阳性见于胰头癌胆囊肿大，均不同"},{"q":"大量放腹水后时，可见","o":["腹壁紧张度增加","腹壁紧张度减低","肝颈静脉回流征阳性","Courvoisier征阳性","振水音"],"a":1,"e":"大量放腹腔积液后腹肌张力降低、失去弹性，故腹壁紧张度减低，也见于慢性消耗性疾病及年老体弱者。腹壁紧张度增加见于急性腹膜炎或腹腔内容物增加；肝颈静脉回流征阳性为右心衰竭；Courvoisier征阳性见于胰头癌；振水音提示幽门梗阻，均非放腹水后改变"},{"q":"右心衰竭时，可见","o":["腹壁紧张度增加","腹壁紧张度减低","肝颈静脉回流征阳性","Courvoisier征阳性","振水音"],"a":2,"e":"右心衰竭致体循环淤血，压迫淤血肝脏使回心血量增加，充血的右心房不能接受而致颈静脉压上升，故肝颈静脉回流征阳性。腹壁紧张度增加见于腹膜炎；腹壁紧张度减低见于大量放腹水后；Courvoisier征阳性见于胰头癌；振水音提示幽门梗阻，均与右心衰无关"},{"q":"上腹壁反射中枢位于","o":["胸髓第7、8节","胸髓第9、10节","胸髓第11、12节","颈髓第5、6节","腰髓第2～4节"],"a":0,"e":"腹壁反射按划拨部位分上、中、下三部，沿肋缘下轻划对应上腹壁反射，中枢在胸髓7～8节。中腹壁反射中枢在胸髓9～10节；下腹壁反射在胸髓11～12节；肱二头肌反射中枢在颈髓5～6节；膝反射中枢在腰髓2～4节，节段各不相同"},{"q":"肱二头肌反射中枢位于","o":["胸髓第7、8节","胸髓第9、10节","胸髓第11、12节","颈髓第5、6节","腰髓第2～4节"],"a":3,"e":"肱二头肌反射检查时叩击肱二头肌腱致前臂屈曲，反射中枢在颈髓5～6节。上腹壁反射中枢在胸髓7～8节；中腹壁反射在胸髓9～10节；下腹壁反射在胸髓11～12节；膝反射中枢在腰髓2～4节，均与颈髓5～6节不同"},{"q":"中腹壁反射中枢位于","o":["胸髓第7、8节","胸髓第9、10节","胸髓第11、12节","颈髓第5、6节","腰髓第2～4节"],"a":1,"e":"中腹壁反射沿脐平方向轻划腹壁，反射中枢在胸髓9～10节。上腹壁反射中枢在胸髓7～8节；下腹壁反射在胸髓11～12节；肱二头肌反射在颈髓5～6节；膝反射在腰髓2～4节，各反射的脊髓节段依次不同"},{"q":"膝反射中枢位于","o":["胸髓第7、8节","胸髓第9、10节","胸髓第11、12节","颈髓第5、6节","腰髓第2～4节"],"a":4,"e":"膝反射叩击髌韧带致小腿伸直，反射中枢在腰髓2～4节。肱二头肌反射中枢在颈髓5～6节；上腹壁反射在胸髓7～8节；中腹壁反射在胸髓9～10节；下腹壁反射在胸髓11～12节，均位于更高节段，与膝反射不同"},{"q":"胆总管结石多表现为","o":["右上腹绞痛伴右肩背部放射痛，发热","右上腹饥饿性疼痛，反酸，嗳气","右上腹闷胀不适、嗳气、厌油腻","右上腹痛，寒战高热，恶心呕吐，黄疸","上腹部闷胀不适，伴腰背部束带样痛，食欲减退"],"a":3,"e":"胆总管结石阻塞胆道并继发感染，出现右上腹痛、寒战高热、黄疸，即夏科三联征，可伴恶心呕吐。右上腹绞痛伴右肩背放射及发热多见于急性胆囊炎、胆囊结石；饥饿性疼痛、反酸嗳气提示十二指肠溃疡；厌油腻、闷胀不适见于慢性胆囊炎；束带样痛伴食欲减退提示胰腺病变"},{"q":"急性胆囊炎、胆囊结石多表现为","o":["右上腹绞痛伴右肩背部放射痛，发热","右上腹饥饿性疼痛，反酸，嗳气","右上腹闷胀不适、嗳气、厌油腻","右上腹痛，寒战高热，恶心呕吐，黄疸","上腹部闷胀不适，伴腰背部束带样痛，食欲减退"],"a":0,"e":"急性胆囊炎、胆囊结石因结石嵌顿及炎症刺激，表现为右上腹绞痛并向右肩背部放射，伴发热。右上腹痛、寒战高热、黄疸为胆总管结石的夏科三联征；饥饿性疼痛、反酸嗳气为十二指肠溃疡；厌油腻、闷胀不适为慢性胆囊炎；腰背束带样痛提示胰腺病变"},{"q":"慢性胆囊炎、胆囊结石多表现为","o":["右上腹绞痛伴右肩背部放射痛，发热","右上腹饥饿性疼痛，反酸，嗳气","右上腹闷胀不适、嗳气、厌油腻","右上腹痛，寒战高热，恶心呕吐，黄疸","上腹部闷胀不适，伴腰背部束带样痛，食欲减退"],"a":2,"e":"慢性胆囊炎、胆囊结石因胆囊功能减退，表现为右上腹闷胀不适、嗳气、厌油腻等消化不良症状。右上腹绞痛伴右肩背放射及发热见于急性胆囊炎；寒战高热、黄疸为胆总管结石；饥饿性疼痛、反酸嗳气为十二指肠溃疡；腰背束带样痛、食欲减退提示胰腺癌或胰腺炎"},{"q":"用于门急诊患者的临时检验的尿液类型是","o":["晨尿","餐后2h尿","随机尿","24h尿","3h尿"],"a":2,"e":"随机尿可随时采集、方便易得，影响因素虽多但适合门急诊患者的临时检验。晨尿浓缩酸化、有形成分浓度高，用于有形成分及早孕检查；餐后2h尿用于尿糖等；24h尿用于化学成分定量；3h尿用于白细胞排泄率等有形成分计数，均不适合门急诊临时检验"},{"q":"用于对尿中蛋白质排泄总量进行定量监测的标本是","o":["晨尿","餐后2h尿","随机尿","24h尿","3h尿"],"a":3,"e":"24h尿收集全天尿液，能反映全天化学成分排泄总量，故用于尿蛋白排泄总量的定量监测。晨尿适用于有形成分和早孕检查；随机尿用于门急诊临时检验；餐后2h尿用于病理性尿蛋白、尿糖；3h尿用于白细胞排泄率等有形成分计数，均不能定量全天蛋白总量"},{"q":"用于尿糖测定的标本是","o":["晨尿","餐后2h尿","随机尿","24h尿","3h尿"],"a":1,"e":"餐后尿（午餐后2小时）用于检查病理性尿蛋白、尿糖和尿胆原，进食后血糖升高易检出尿糖。晨尿浓缩，用于有形成分及早孕检查；随机尿用于门急诊临时检验；24h尿用于化学成分定量；3h尿用于白细胞排泄率，均非尿糖测定常规标本"},{"q":"用于尿沉渣检测的标本是","o":["晨尿","餐后2h尿","随机尿","24h尿","3h尿"],"a":0,"e":"晨尿为清晨第一次尿，浓缩酸化，有形成分和化学成分浓度高，故适用于尿沉渣等有形成分检查。随机尿采集方便但影响因素多，适合门急诊筛查；餐后2h尿用于尿糖、尿蛋白；24h尿用于化学成分定量；3h尿用于白细胞排泄率，均不如晨尿适合沉渣检查"},{"q":"肥胖者的体重为超过标准体重的","o":["3%","5%","10%","15%","20%"],"a":4,"e":"通常认为超过标准体重10%为超重，超过20%为肥胖，需排除肌肉发达或水分潴留因素。3%与5%属正常体重波动；10%为超重界线而非肥胖；15%介于超重与肥胖之间，均未达肥胖标准，故20%为正确界值"},{"q":"消瘦者的体重为减轻到低于正常的","o":["3%","5%","10%","15%","20%"],"a":2,"e":"体重低于标准体重10%可诊断为消瘦，因各种原因致体重低于正常低限，BMI＜18.5亦提示消瘦。3%与5%属正常波动；15%与20%为明显消瘦的程度描述但非诊断界线；超过标准体重10%、20%分别为超重与肥胖，方向相反，均非消瘦界值"},{"q":"现病史包括","o":["子女的健康状况","配偶的健康状况","冶游史","预防接种史","诊治经过"],"a":4,"e":"现病史记录疾病发生、发展、演变和诊治经过，诊治经过属其内容，包括本次就诊前接受的诊断、治疗及用药情况。子女健康状况属家族史；配偶健康状况属婚姻史；冶游史属个人史；预防接种史属既往史，均不属现病史"},{"q":"家族史包括","o":["子女的健康状况","配偶的健康状况","冶游史","预防接种史","诊治经过"],"a":0,"e":"家族史包括双亲、兄弟姐妹及子女的健康与疾病情况，特别注意有无遗传病及与患者相同的疾病，故子女健康状况属家族史。配偶健康状况属婚姻史；冶游史属个人史；预防接种史属既往史；诊治经过属现病史，均非家族史内容"},{"q":"婚姻史包括","o":["子女的健康状况","配偶的健康状况","冶游史","预防接种史","诊治经过"],"a":1,"e":"婚姻史包括婚姻状况、结婚年龄、配偶健康状况、性生活情况及夫妻关系，故配偶健康状况属婚姻史。子女健康状况属家族史；冶游史属个人史；预防接种史属既往史；诊治经过属现病史，均不归婚姻史"},{"q":"既往史包括","o":["子女的健康状况","配偶的健康状况","冶游史","预防接种史","诊治经过"],"a":3,"e":"既往史包括既往健康状况、曾患疾病、外伤手术、预防接种史及过敏史，故预防接种史属既往史。子女健康状况属家族史；配偶健康状况属婚姻史；冶游史属个人史；诊治经过属现病史，均与既往史内容不符"},{"q":"急性心肌梗死的表现是","o":["常由风湿热所致，心尖部可闻及隆隆样舒张中晚期杂音，伴震颤","有高血压、糖尿病病史，在劳累、情绪激动诱因下出现胸骨后压榨性疼痛，可自行缓解或口服硝酸甘油后缓解，心肌酶谱检查可无异常","有呼吸道感染病史，后出现乏力、心悸，心律失常，心肌酶升高","有高血压、冠心病病史，无明显诱因下出现持续性胸痛、阵发性加重，持续时间长，口服硝酸甘油作用差或无效，心电图提示ST-T改变，心肌酶升高","多伴有发热，主要累及二尖瓣及主动脉瓣，有赘生物形成"],"a":3,"e":"急性心肌梗死多有高血压、冠心病基础，无明显诱因出现持续性胸痛、阵发性加重，时间长且硝酸甘油无效，心电图ST-T改变、心肌酶升高。心尖部隆隆样舒张中晚期杂音伴震颤为二尖瓣狭窄；劳累诱发、硝酸甘油可缓解、心肌酶正常为心绞痛；呼吸道感染后心肌酶升高为心肌炎；发热伴赘生物为感染性心内膜炎"},{"q":"心肌炎的表现是","o":["常由风湿热所致，心尖部可闻及隆隆样舒张中晚期杂音，伴震颤","有高血压、糖尿病病史，在劳累、情绪激动诱因下出现胸骨后压榨性疼痛，可自行缓解或口服硝酸甘油后缓解，心肌酶谱检查可无异常","有呼吸道感染病史，后出现乏力、心悸，心律失常，心肌酶升高","有高血压、冠心病病史，无明显诱因下出现持续性胸痛、阵发性加重，持续时间长，口服硝酸甘油作用差或无效，心电图提示ST-T改变，心肌酶升高","多伴有发热，主要累及二尖瓣及主动脉瓣，有赘生物形成"],"a":2,"e":"心肌炎常有呼吸道感染前驱史，随后出现乏力、心悸、心律失常及心肌酶升高，因病毒感染累及心肌。风湿热致心尖隆隆样舒张期杂音为二尖瓣狭窄；劳累诱发胸痛、硝酸甘油缓解为心绞痛；持续胸痛、硝酸甘油无效、ST-T改变为心肌梗死；发热伴赘生物为感染性心内膜炎"},{"q":"老年人肺底部可听到","o":["粗湿啰音","干啰音","中、细湿啰音","捻发音","胸膜摩擦音"],"a":3,"e":"正常老年人或长期卧床者肺底可闻及捻发音，为细支气管和肺泡壁黏着陷闭后吸气冲开所致，数次深呼吸或咳嗽后消失，多无临床意义。粗湿啰音见于支气管扩张、肺水肿；干啰音为气道狭窄所致；中细湿啰音见于肺炎、肺淤血；胸膜摩擦音为胸膜炎体征，均不同"},{"q":"支气管肺炎时可听到","o":["粗湿啰音","干啰音","中、细湿啰音","捻发音","胸膜摩擦音"],"a":2,"e":"支气管肺炎时肺泡与细支气管渗出，两侧肺底可闻及中、细湿啰音，两肺野满布时提示病变广泛。粗湿啰音见于气管、主支气管病变或肺水肿；干啰音为气道狭窄或部分阻塞；捻发音为细支气管肺泡黏着音，老年人肺底可闻及；胸膜摩擦音见于胸膜炎"},{"q":"有助于伤寒的诊断","o":["肥达反应结果O 1∶160，H 1∶40，A 1∶40，B 1∶40","肥达反应结果O 1∶160，H 1∶320，A 1∶40，B -","肥达反应结果O 1∶320，H 1∶80，A 1∶320，B 1∶40","肥达反应结果O 1∶40，H 1∶320，A 1∶320，B 1∶320","肥达反应结果O 1∶320，H 1∶40，A 1∶40，B 1∶640"],"a":1,"e":"伤寒诊断价值在于O效价＞1∶80且H＞1∶160，O 1∶160、H 1∶320符合此标准且副伤寒效价不高。O不高而H单独升高多为疫苗注射或非特异性回忆反应；O升高H不高提示感染早期或交叉感染；副伤寒甲、乙效价显著升高分别提示相应副伤寒，均非伤寒典型"},{"q":"由注射伤寒副伤寒疫苗或非特异性回忆反应所致","o":["肥达反应结果O 1∶160，H 1∶40，A 1∶40，B 1∶40","肥达反应结果O 1∶160，H 1∶320，A 1∶40，B -","肥达反应结果O 1∶320，H 1∶80，A 1∶320，B 1∶40","肥达反应结果O 1∶40，H 1∶320，A 1∶320，B 1∶320","肥达反应结果O 1∶320，H 1∶40，A 1∶40，B 1∶640"],"a":3,"e":"注射伤寒副伤寒疫苗或非特异性回忆反应表现为O不高而H升高，O 1∶40、H 1∶320且副伤寒效价不高即属此。O、H均升高提示伤寒现症感染；O升高H不高见于感染早期；副伤寒甲效价显著升高提示副伤寒甲；副伤寒乙效价升高提示副伤寒乙，均不同"},{"q":"有助于副伤寒甲的诊断","o":["肥达反应结果O 1∶160，H 1∶40，A 1∶40，B 1∶40","肥达反应结果O 1∶160，H 1∶320，A 1∶40，B -","肥达反应结果O 1∶320，H 1∶80，A 1∶320，B 1∶40","肥达反应结果O 1∶40，H 1∶320，A 1∶320，B 1∶320","肥达反应结果O 1∶320，H 1∶40，A 1∶40，B 1∶640"],"a":2,"e":"副伤寒甲诊断依据副伤寒甲鞭毛抗原A效价升高（＞1∶80），O 1∶320、A 1∶320符合且其他不高。O、H均升高提示伤寒；O不高而H高为疫苗接种回忆反应；O高H不高为感染早期；B效价显著升高提示副伤寒乙，均非副伤寒甲"},{"q":"表示可能是沙门氏菌感染的早期","o":["肥达反应结果O 1∶160，H 1∶40，A 1∶40，B 1∶40","肥达反应结果O 1∶160，H 1∶320，A 1∶40，B -","肥达反应结果O 1∶320，H 1∶80，A 1∶320，B 1∶40","肥达反应结果O 1∶40，H 1∶320，A 1∶320，B 1∶320","肥达反应结果O 1∶320，H 1∶40，A 1∶40，B 1∶640"],"a":0,"e":"沙门菌感染早期仅O抗体升高而H不高，O 1∶160、H 1∶40即为感染早期表现。O、H均高提示伤寒现症；O不高H高为疫苗接种或回忆反应；A效价高提示副伤寒甲；B效价高提示副伤寒乙，均非早期感染的抗体格局"},{"q":"安静状态下，明显的颈动脉搏动可见于","o":["二尖瓣关闭不全","三尖瓣关闭不全","主动脉瓣关闭不全","二尖瓣狭窄","主动脉瓣狭窄"],"a":2,"e":"安静状态下出现明显颈动脉搏动，多见于主动脉瓣关闭不全、高血压、甲亢及严重贫血，因脉压增大、心搏出量增加。二尖瓣关闭不全及三尖瓣关闭不全主要表现为颈静脉搏动；二尖瓣狭窄致颈静脉怒张；主动脉瓣狭窄脉压减小，均不会出现明显颈动脉搏动"},{"q":"安静状态下，明显的颈静脉搏动可见于","o":["二尖瓣关闭不全","三尖瓣关闭不全","主动脉瓣关闭不全","二尖瓣狭窄","主动脉瓣狭窄"],"a":1,"e":"颈静脉搏动可见于三尖瓣关闭不全，因右心室收缩时血液反流至右房、颈静脉，伴肝脏收缩期搏动。二尖瓣关闭不全无明显颈静脉搏动；主动脉瓣关闭不全为颈动脉搏动；二尖瓣狭窄致颈静脉怒张但无搏动；主动脉瓣狭窄脉压小，均非颈静脉搏动原因"},{"q":"由于矢状缝和冠状缝过早闭合所致的是","o":["尖颅","方颅","巨颅","长颅","变形颅"],"a":0,"e":"尖颅（塔颅）头顶部尖突高起，因矢状缝与冠状缝过早闭合所致，见于Apert综合征。方颅前额突出、头顶平坦，见于佝偻病或先天梅毒；巨颅额顶颞枕膨大，因颅内压增高（脑积水）；长颅与变形颅分别见于肢端肥大症和颅骨畸形，均非缝线早闭所致"},{"q":"由于颅内压增高所致的是","o":["尖颅","方颅","巨颅","长颅","变形颅"],"a":2,"e":"巨颅因颅内压增高（脑积水）致额、顶、颞、枕部膨大呈圆形，面部相对很小，可出现落日现象。尖颅因矢状缝与冠状缝早闭而顶部尖突；方颅见于佝偻病或先天梅毒；长颅见于肢端肥大症；变形颅为颅骨软化或畸形，均非颅内压增高所致"},{"q":"二尖瓣狭窄杂音更明显见于","o":["左侧卧位","坐位前倾","仰卧位","卧位或下蹲位到迅速站立","立位或坐位迅速平卧"],"a":0,"e":"二尖瓣狭窄的舒张期隆隆样杂音在左侧卧位时更明显，因该体位使左房血流加速、杂音增强，是其最重要体征。坐位前倾使主动脉瓣关闭不全叹气样杂音更清晰；仰卧位使二尖瓣、三尖瓣、肺动脉瓣关闭不全杂音更明显；立位或坐位迅速平卧增加回心血量；迅速站立则使多数杂音减轻，均非二尖瓣狭窄的最佳体位"},{"q":"主动脉瓣关闭不全的杂音更明显见于","o":["左侧卧位","坐位前倾","仰卧位","卧位或下蹲位到迅速站立","立位或坐位迅速平卧"],"a":1,"e":"主动脉瓣关闭不全的舒张期叹气样杂音在坐位前倾、深呼气后屏气时最清楚，前倾使心脏靠近胸壁。左侧卧位使二尖瓣狭窄杂音更明显；仰卧位使二尖瓣、三尖瓣、肺动脉瓣关闭不全杂音明显；由卧位迅速站立使杂音减轻；立位迅速平卧回心血量增加，均非主动脉瓣关闭不全的最佳体位"},{"q":"提示真菌感染的是","o":["铁锈色痰","黄绿色痰","白色黏稠痰","粉红色泡沫痰","砖红色痰"],"a":2,"e":"痰白黏稠且呈拉丝状提示真菌感染（如白念珠菌），因菌丝与黏液混合形成拉丝痰。铁锈色痰为肺炎链球菌肺炎特征；黄绿色痰提示铜绿假单胞菌感染；粉红色泡沫痰为急性肺水肿表现；砖红色胶冻样痰见于肺炎克雷伯杆菌肺炎，均非真菌感染"},{"q":"肺水肿特有的表现是","o":["铁锈色痰","黄绿色痰","白色黏稠痰","粉红色泡沫痰","砖红色痰"],"a":3,"e":"急性肺水肿时肺毛细血管压骤升，液体与红细胞渗入肺泡，咯大量粉红色泡沫痰，并伴端坐呼吸、大汗、交替脉。铁锈色痰见于大叶性肺炎；黄绿色痰提示铜绿假单胞菌感染；白色黏稠痰提示真菌感染或支气管炎；砖红色胶冻样痰见于克雷伯杆菌肺炎，均非肺水肿表现"},{"q":"主动脉瓣关闭不全的舒张期杂音类型是","o":["递增型","递减型","递增递减型","连续型","一贯型"],"a":1,"e":"主动脉瓣关闭不全的舒张期杂音由较强逐渐减弱，呈递减型，为主动脉瓣第二听诊区叹气样杂音。递增型由弱渐强，见于二尖瓣狭窄舒张期杂音；递增递减型（菱形）见于主动脉瓣狭窄收缩期杂音；连续型见于动脉导管未闭；一贯型强度恒定，见于二尖瓣关闭不全全收缩期杂音"},{"q":"二尖瓣关闭不全的收缩期杂音类型是","o":["递增型","递减型","递增递减型","连续型","一贯型"],"a":4,"e":"二尖瓣关闭不全的全收缩期杂音强度大体保持一致，呈一贯型（平台型），为心尖区粗糙吹风样杂音。递增型由弱渐强，见于二尖瓣狭窄；递减型由强渐弱，见于主动脉瓣关闭不全；递增递减型为菱形，见于主动脉瓣狭窄；连续型见于动脉导管未闭，均非二尖瓣关闭不全形态"},{"q":"二尖瓣狭窄的舒张期杂音类型是","o":["递增型","递减型","递增递减型","连续型","一贯型"],"a":0,"e":"二尖瓣狭窄的舒张期隆隆样杂音由弱逐渐增强，呈递增型，左侧卧位更明显且常伴震颤。递减型由强渐弱，见于主动脉瓣关闭不全；递增递减型为菱形，见于主动脉瓣狭窄；连续型自收缩期持续至舒张期，见于动脉导管未闭；一贯型强度恒定，见于二尖瓣关闭不全，均非二尖瓣狭窄"},{"q":"脊柱椎体破坏、压缩，形成特征性的成角畸形的疾病是","o":["脊柱外伤","佝偻病","脊柱结核","脊柱退行性变","强直性脊柱炎"],"a":2,"e":"脊柱结核多在青少年发病，病变位于胸椎下段及腰段，椎体被破坏、压缩、棘突后凸，后期形成特征性成角畸形。脊柱外伤后畸形多由骨折错位所致；佝偻病坐位时胸段均匀后弯、仰卧位消失；脊柱退行性变以骨质增生、活动受限为主；强直性脊柱炎呈弧形后凸并强直固定"},{"q":"坐位时胸段脊柱呈均匀性向后弯，仰卧位时可消失的疾病是","o":["脊柱外伤","佝偻病","脊柱结核","脊柱退行性变","强直性脊柱炎"],"a":1,"e":"佝偻病多在儿童期发病，坐位时胸段呈明显均匀性向后弯曲，仰卧位时弯曲可消失。脊柱外伤后畸形由骨折错位引起，体位改变不消失；脊柱结核椎体破坏形成成角畸形；脊柱退行性变以骨质增生为主；强直性脊柱炎胸段弧形后凸、仰卧位亦不能伸直，均不同"},{"q":"脊柱胸段成弧形后凸，脊柱活动明显受限，仰卧位时亦不能伸直的疾病是","o":["脊柱外伤","佝偻病","脊柱结核","脊柱退行性变","强直性脊柱炎"],"a":4,"e":"强直性脊柱炎多见于成年人，脊柱胸段呈弧形（弓形）后凸，脊柱强直固定、活动明显受限，仰卧位亦不能伸直。佝偻病后凸均匀且仰卧位可消失；脊柱结核为椎体破坏后的成角畸形；脊柱外伤有骨折错位史；脊柱退行性变以骨质增生、活动稍受限为主，均非强直固定"},{"q":"通常叩诊心界时需识别的叩诊音是","o":["清音","浊音","实音","鼓音","过清音"],"a":1,"e":"叩诊心界时板指由外向内移动，以声音由清变浊来确定心脏相对浊音界，故需识别浊音。清音为正常肺野叩诊音；实音为不含气实质脏器或大量胸腔积液、肺实变；鼓音见于胃泡区、腹部及气胸；过清音为肺气肿等含气增多时的病态音，均非心界叩诊的判定音"},{"q":"正常成人腹部叩诊音多呈","o":["清音","浊音","实音","鼓音","过清音"],"a":3,"e":"正常成人腹部大部分区域叩诊呈鼓音，因胃肠道含气，仅肝脾、增大膀胱子宫及两侧腰肌处为浊音。清音为正常肺部叩诊音；浊音见于肝脾等实质脏器被覆部位；实音见于大量胸腔积液或肺实变；过清音为肺含气增多时的病态音，均非腹部主要叩诊音"},{"q":"正常青年人不会出现的叩诊音是","o":["清音","浊音","实音","鼓音","过清音"],"a":4,"e":"过清音介于鼓音与清音之间，音调低、音响强，是正常成人不会出现的病态叩击音，见于肺气肿等肺含气量增多、弹性减弱时。清音为正常肺野叩诊音；浊音为心、肝被肺覆盖部分的叩诊音；实音见于实质脏器、大量胸腔积液；鼓音见于胃泡区与腹部，正常青年人均可出现"},{"q":"正常成人肺部叩诊音是","o":["清音","浊音","实音","鼓音","过清音"],"a":0,"e":"清音为正常含气肺组织的叩诊音，音响中等、音调较低、时限较长，前胸上部因肌肉较厚相对稍浊但仍属清音。浊音与实音提示肺实变或胸膜腔液体，实音见于大量胸腔积液，浊音见于肺炎实变或胸膜增厚。鼓音为含气空腔或气胸，过清音为肺气肿含气过多，均非正常肺叩诊音"},{"q":"肺炎克雷伯菌感染时，痰液为","o":["粉红色泡沫痰","砖红色胶冻痰","痰中带血","暗红色黏稠血痰","铁锈色痰"],"a":1,"e":"肺炎克雷伯菌肺炎的痰液由炎性渗出、坏死组织与血液混合，呈砖红色胶冻样，黏稠而量多，为其特征。铁锈色痰是肺炎链球菌肺炎的典型表现；粉红色泡沫痰为急性左心衰竭肺水肿；暗红色黏稠血痰见于肺栓塞或肺梗死；痰中带血多见于肺结核、肺癌等慢性消耗或占位性病变"},{"q":"肺梗死时，痰液为","o":["粉红色泡沫痰","砖红色胶冻痰","痰中带血","暗红色黏稠血痰","铁锈色痰"],"a":3,"e":"肺栓塞或肺梗死时肺血管阻塞、局部肺组织缺血坏死，咯血量可不多但血液黏稠、呈暗红色。砖红色胶冻痰为肺炎克雷伯菌肺炎特征；粉红色泡沫痰见于急性左心衰竭；铁锈色痰为肺炎链球菌肺炎；痰中带血仅为小量出血的泛指，缺乏梗死的特异性"},{"q":"急性左心衰竭时，痰液为","o":["粉红色泡沫痰","砖红色胶冻痰","痰中带血","暗红色黏稠血痰","铁锈色痰"],"a":0,"e":"急性左心衰竭时肺静脉压骤升，肺毛细血管内液体与红细胞渗入肺泡，形成浆液性粉红色泡沫痰，常伴夜间阵发性呼吸困难、端坐呼吸及两肺湿啰音。砖红色胶冻痰为肺炎克雷伯菌肺炎；铁锈色痰属肺炎链球菌肺炎；暗红色黏稠血痰见于肺栓塞；痰中带血多提示结核或肺癌"},{"q":"窦性心律不齐时，可见","o":["吸气时脉率增快，呼气时减慢","脉率少于心率，且强弱快慢不规则","脉搏不齐，提前出现1次脉搏，其后有较长间歇","每2次正常脉搏后出现1次提前搏动","每分钟脉搏110次，律齐"],"a":0,"e":"窦性心律不齐由呼吸中枢与迷走神经张力周期性变化所致，吸气时迷走抑制减弱、心率增快，呼气时减慢，多见于青少年，无临床意义。B项描述的是心房颤动的脉搏短绌；C项为期前收缩后代偿间歇的表现；D项为二联脉，即每次正常搏动后固定出现一次提前搏动；E项为窦性心动过速，节律规则而不随呼吸变化"},{"q":"期前收缩时，可见","o":["吸气时脉率增快，呼气时减慢","脉率少于心率，且强弱快慢不规则","脉搏不齐，提前出现1次脉搏，其后有较长间歇","每2次正常脉搏后出现1次提前搏动","每分钟脉搏110次，律齐"],"a":2,"e":"期前收缩是在规则心律基础上提前出现一次异位搏动，其后因窦房结重建或干扰出现代偿间歇，故脉搏不齐并有较长间歇。A项为窦性心律不齐的呼吸性变化；B项为心房颤动的脉搏短绌；D项为二联脉，即每两次正常搏动后跟一次提前搏动的情形；E项为窦性心动过速，脉律规则"},{"q":"心房颤动时，可见","o":["吸气时脉率增快，呼气时减慢","脉率少于心率，且强弱快慢不规则","脉搏不齐，提前出现1次脉搏，其后有较长间歇","每2次正常脉搏后出现1次提前搏动","每分钟脉搏110次，律齐"],"a":1,"e":"心房颤动时心室律绝对不规则，心室充盈量不等致第一心音强弱不等，部分收缩搏出量过低不能产生周围脉搏，形成脉搏短绌，故脉率少于心率。A项为窦性心律不齐；C项为期前收缩伴代偿间歇；D项为二联脉；E项为窦性心动过速，三者均无脉搏短绌"},{"q":"患侧胸廓饱满，叩诊浊音的是","o":["胸膜炎","大量胸腔积液","肺脓肿","肺气肿","单侧气胸"],"a":1,"e":"大量胸腔积液使患侧胸廓饱满、肋间隙增宽，液体阻隔含气肺组织，叩诊由清音转为浊音或实音，语音震颤减弱，气管推向健侧。E项单侧气胸虽也胸廓饱满，但叩诊为鼓音而非浊音；D项肺气肿为双侧过清音；A项胸膜炎以胸膜摩擦感、摩擦音为主；C项肺脓肿以空腔及湿啰音为著"},{"q":"单侧语音震颤减弱伴叩诊鼓音的是","o":["胸膜炎","大量胸腔积液","肺脓肿","肺气肿","单侧气胸"],"a":4,"e":"气胸时胸膜腔积气，肺被压缩、含气量减少且声波传导受阻，语音震颤减弱或消失，叩诊呈鼓音，患侧胸廓饱满、气管移向健侧。B项大量胸腔积液语音震颤亦减弱，但叩诊为实音；D项肺气肿为双侧过清音、震颤双侧减弱；A项胸膜炎以摩擦感为主；C项肺脓肿多为浊音及空腔体征"},{"q":"有胸膜摩擦感的是","o":["胸膜炎","大量胸腔积液","肺脓肿","肺气肿","单侧气胸"],"a":0,"e":"急性纤维蛋白性胸膜炎时两层胸膜表面因纤维蛋白沉着而粗糙，呼吸时相互摩擦产生胸膜摩擦感，常同时闻及胸膜摩擦音，屏气后消失。B项大量胸腔积液使两层胸膜分开，摩擦感反而消失；C项肺脓肿以发热、脓痰及空腔体征为主；D项肺气肿为双侧过清音；E项气胸为鼓音、呼吸音消失"},{"q":"语音震颤增强的是","o":["胸膜炎","大量胸腔积液","肺脓肿","肺气肿","单侧气胸"],"a":2,"e":"语音震颤增强见于肺实变或接近胸膜的肺内巨大空腔，肺脓肿空洞内声波共鸣，若周围有炎性浸润并与胸壁粘连则传导更强。B项大量胸腔积液和E项气胸均使震颤减弱或消失；A项胸膜炎以摩擦感为主；D项肺气肿肺泡含气过多，震颤双侧减弱"},{"q":"败血症时可见","o":["呕血伴黄疸","呕血伴皮肤黏膜出血","呕血伴下肢水肿","呕血伴视力下降","呕血伴腹泻"],"a":2,"e":"官方答案为【呕血伴下肢水肿】，但依据教材，正确答案为【呕血伴皮肤黏膜出血】。败血症为严重全身感染，常继发弥散性血管内凝血与血小板消耗，故呕血伴皮肤黏膜出血，并多寒战高热。下肢水肿提示肝硬化门静脉高压低蛋白状态，并非败血症特征，原答案混淆了水肿病因；伴黄疸、寒战及出血则见于钩端螺旋体病"},{"q":"胆道结石并梗阻时可见","o":["呕血伴黄疸","呕血伴皮肤黏膜出血","呕血伴下肢水肿","呕血伴视力下降","呕血伴腹泻"],"a":0,"e":"胆道结石梗阻导致胆汁淤积，结合胆红素反流入血出现黄疸；若蚀破胆道黏膜或并发胆道出血，可呕血并伴右上腹绞痛、寒战发热。B项呕血伴皮肤黏膜出血指向白血病、弥散性血管内凝血等出血性疾病；C项伴下肢水肿多为肝硬化门静脉高压；E项伴腹泻常见于急性胃肠炎或霍乱"},{"q":"白血病时可见","o":["呕血伴黄疸","呕血伴皮肤黏膜出血","呕血伴下肢水肿","呕血伴视力下降","呕血伴腹泻"],"a":1,"e":"白血病时骨髓异常增生抑制正常造血，血小板减少并伴凝血异常，故呕血同时有皮肤黏膜出血、贫血与发热，常伴肝脾肿大。A项伴黄疸为胆道疾病或肝细胞损伤；C项伴下肢水肿多见于肝硬化失代偿；E项伴腹泻提示急性肠道感染；D项视力下降与呕血无直接对应关系"},{"q":"肺泡呼吸音减弱见于","o":["代谢性碱中毒","代谢性酸中毒","肺结核","压迫性肺不张","压迫性肺膨胀不全"],"a":4,"e":"胸腔积液或气胸压迫肺组织使其膨胀受限，肺泡通气量减少，呼吸音传导减弱，故见压迫性肺膨胀不全。D项压迫性肺不张因肺组织致密、支气管音传导良好，反而可在积液区上方听到强度较弱而遥远的支气管呼吸音；A、B项代谢性酸碱失衡主要改变呼吸深度和节律，如Kussmaul呼吸；C项肺结核多表现为局部呼吸音改变"},{"q":"管样呼吸音见于","o":["代谢性碱中毒","代谢性酸中毒","肺结核","压迫性肺不张","压迫性肺膨胀不全"],"a":3,"e":"管样呼吸音是支气管音传入肺泡区域所致，压迫性肺不张时肺组织致密，有利于支气管音传导，故在积液区上方听到强度较弱、位置遥远的支气管呼吸音。E项压迫性肺膨胀不全时肺泡含气减少、传导不良，以肺泡呼吸音减弱为主；C项肺结核多见异常支气管肺泡呼吸音；A、B项酸碱失衡改变呼吸节律而非呼吸音性质"},{"q":"异常支气管肺泡呼吸音见于","o":["代谢性碱中毒","代谢性酸中毒","肺结核","压迫性肺不张","压迫性肺膨胀不全"],"a":2,"e":"异常支气管肺泡呼吸音产生于肺实变区域较小且与含气肺组织混合存在，或实变部位较深被正常肺组织覆盖，常见于支气管肺炎、肺结核及大叶性肺炎初期。D项压迫性肺不张多产生支气管呼吸音；E项压迫性肺膨胀不全以肺泡呼吸音减弱为主；A、B项代谢性酸碱失衡表现为Kussmaul呼吸等节律改变"},{"q":"肺气肿时的呼吸是","o":["吸气显著费力，严重者可出现“三凹征”","呼气费力，呼气缓慢，呼吸时间明显延长","吸气及呼气均感呼吸费力，频率增快，深度变浅","夜间睡眠中突感胸闷气急，被迫坐起，惊恐不安","深长而规则的呼吸，可伴有鼾音"],"a":1,"e":"肺气肿时肺泡弹性减弱、小支气管痉挛或炎症，呼气气流受限，需用力呼气且呼气时间明显延长，属呼气性呼吸困难，常伴哮鸣音。A项为吸气性呼吸困难，见于大气道阻塞伴三凹征；C项为混合性呼吸困难，见于重症肺炎、肺纤维化；D项为急性左心衰竭夜间阵发性呼吸困难；E项为酸中毒深大呼吸"},{"q":"大气道阻塞导致的呼吸困难表现为","o":["吸气显著费力，严重者可出现“三凹征”","呼气费力，呼气缓慢，呼吸时间明显延长","吸气及呼气均感呼吸费力，频率增快，深度变浅","夜间睡眠中突感胸闷气急，被迫坐起，惊恐不安","深长而规则的呼吸，可伴有鼾音"],"a":0,"e":"喉、气管等大气道狭窄或阻塞时吸气气流受限，吸气肌极度用力使胸腔负压增大，出现胸骨上窝、锁骨上窝及肋间隙凹陷，即三凹征，属吸气性呼吸困难。B项为呼气性呼吸困难，见于肺气肿、哮喘，因小气道痉挛、肺泡弹性减弱；C项为混合性呼吸困难；D项为心源性哮喘；E项为代谢性酸中毒的Kussmaul呼吸"},{"q":"急性左心衰竭的呼吸是","o":["吸气显著费力，严重者可出现“三凹征”","呼气费力，呼气缓慢，呼吸时间明显延长","吸气及呼气均感呼吸费力，频率增快，深度变浅","夜间睡眠中突感胸闷气急，被迫坐起，惊恐不安","深长而规则的呼吸，可伴有鼾音"],"a":3,"e":"急性左心衰竭夜间平卧时回心血量增加、肺淤血加重，突发胸闷气急被迫坐起，即夜间阵发性呼吸困难，重者端坐呼吸、发绀、咳粉红色泡沫痰。A项为吸气性呼吸困难伴三凹征；B项为呼气性呼吸困难；C项为混合性呼吸困难；E项为酸中毒深大呼吸，均非左心衰竭的典型节律"},{"q":"糖尿病酮症酸中毒的呼吸困难表现为","o":["吸气显著费力，严重者可出现“三凹征”","呼气费力，呼气缓慢，呼吸时间明显延长","吸气及呼气均感呼吸费力，频率增快，深度变浅","夜间睡眠中突感胸闷气急，被迫坐起，惊恐不安","深长而规则的呼吸，可伴有鼾音"],"a":4,"e":"酮症酸中毒时酸性代谢产物刺激呼吸中枢，出现深长而规则的Kussmaul呼吸，可伴鼾音，通过加强通气排出二氧化碳以代偿酸中毒。A项为大气道阻塞的吸气性呼吸困难伴三凹征；B项为肺气肿、哮喘的呼气性呼吸困难；C项为混合性呼吸困难；D项为急性左心衰竭夜间阵发性呼吸困难"},{"q":"对抑郁的患者","o":["适当的鼓励患者讲出其感受","应采取坦然、理解、不卑不亢的态度","分次进行告知，告诉患者问诊的内容及时间限制","语言通俗易懂，注意必要的重复","由家长代述"],"a":0,"e":"抑郁患者情绪低落、言语减少，问诊时应鼓励其讲出感受，安抚理解并适当等待、减慢问诊速度，注意语言与非语言线索。B项坦然、理解、不卑不亢是针对愤怒或敌意患者的态度；C项分次告知、说明时间限制多用于焦虑或时间受限者；D项语言通俗、必要重复针对文化程度低者；E项由家长代述适用于儿童"},{"q":"对有愤怒和敌意的患者","o":["适当的鼓励患者讲出其感受","应采取坦然、理解、不卑不亢的态度","分次进行告知，告诉患者问诊的内容及时间限制","语言通俗易懂，注意必要的重复","由家长代述"],"a":1,"e":"面对愤怒和敌意的患者，医生不能发怒或计较，应坦然、理解、不卑不亢，缓慢清晰询问，找出原因并说明，避免迁怒他人。A项鼓励讲出感受适用于焦虑、抑郁患者；C项分次告知并说明时间限制属对焦虑者的沟通技巧；D项语言通俗、必要重复用于文化程度低者；E项家长代述用于儿童"},{"q":"对文化程度低的患者","o":["适当的鼓励患者讲出其感受","应采取坦然、理解、不卑不亢的态度","分次进行告知，告诉患者问诊的内容及时间限制","语言通俗易懂，注意必要的重复","由家长代述"],"a":3,"e":"文化程度低者理解力和医学知识贫乏，问诊须用通俗易懂语言，减慢速度并适当重复、核实，以保证信息准确。A项鼓励讲出感受用于焦虑抑郁；B项坦然理解不卑不亢用于愤怒敌意；C项分次告知、说明内容与时限针对焦虑者；E项由家长代述用于不能自述病史的儿童"},{"q":"对儿童患者","o":["适当的鼓励患者讲出其感受","应采取坦然、理解、不卑不亢的态度","分次进行告知，告诉患者问诊的内容及时间限制","语言通俗易懂，注意必要的重复","由家长代述"],"a":4,"e":"小儿多不能自述病史，须由家长或保育人员代述，并注意其观察能力与密切程度，5岁以上可补充细节但需核实准确性。A项鼓励讲出感受用于焦虑抑郁者；B项坦然理解不卑不亢用于愤怒敌意者；C项分次告知用于焦虑者；D项语言通俗、必要重复用于文化程度低者"},{"q":"呼气性呼吸困难出现于","o":["呼吸与脉搏之比为1∶4","气管异物","尿毒症酸中毒","急性胸膜炎","支气管哮喘"],"a":4,"e":"呼气性呼吸困难因肺泡弹性减弱或小支气管痉挛炎症，呼气费力、时间延长，伴哮鸣音，见于支气管哮喘和慢性阻塞性肺疾病。A项呼吸与脉搏1∶4为正常成人静息状态；B项气管异物属吸气性呼吸困难伴三凹征；C项尿毒症酸中毒为Kussmaul深大呼吸；D项急性胸膜炎呈抑制性呼吸"},{"q":"吸气性呼吸困难出现于","o":["呼吸与脉搏之比为1∶4","气管异物","尿毒症酸中毒","急性胸膜炎","支气管哮喘"],"a":1,"e":"气管异物等大气道阻塞使吸气气流受限，吸气显著费力并出现三凹征，属吸气性呼吸困难。A项呼吸与脉搏1∶4为正常静息比值；C项尿毒症酸中毒表现为深大规则的Kussmaul呼吸；D项急性胸膜炎因疼痛呈抑制性呼吸；E项支气管哮喘为呼气性呼吸困难，呼气延长伴哮鸣音"},{"q":"正常成人静息状态下","o":["呼吸与脉搏之比为1∶4","气管异物","尿毒症酸中毒","急性胸膜炎","支气管哮喘"],"a":0,"e":"正常成人静息时呼吸12～20次/分，脉搏60～100次/分，呼吸与脉搏之比约为1∶4。B项气管异物表现为吸气性呼吸困难伴三凹征；C项尿毒症酸中毒为深大呼吸；D项急性胸膜炎呈抑制性呼吸，吸气突然受限；E项支气管哮喘为呼气性呼吸困难，呼气时间延长"},{"q":"抑制性呼吸出现于","o":["呼吸与脉搏之比为1∶4","气管异物","尿毒症酸中毒","急性胸膜炎","支气管哮喘"],"a":3,"e":"抑制性呼吸是因胸痛使吸气突然中断、呼吸浅快，见于急性胸膜炎、肋骨骨折及胸部严重外伤，患者常取患侧卧位减轻疼痛。B项气管异物为吸气性呼吸困难伴三凹征；C项尿毒症酸中毒为Kussmaul深大呼吸；E项支气管哮喘为呼气性呼吸困难；A项为正常静息比值"},{"q":"熟睡状态，不易唤醒，压眶时可被唤醒，醒时答话含糊","o":["昏睡","嗜睡","意识模糊","轻度昏迷","中度昏迷"],"a":0,"e":"昏睡是接近人事不省的严重意识障碍，患者处于熟睡状态，不易唤醒，强烈刺激如压迫眶上神经可短暂唤醒，醒时答话含糊，停止刺激很快再入睡。B项嗜睡为最轻意识障碍，可被唤醒且能正确回答；C项意识模糊以定向力障碍为主，能保持简单精神活动；D、E项昏迷不能被唤醒"},{"q":"能保持简单的精神活动，但对时间、地点、人物等定向力发生障碍","o":["昏睡","嗜睡","意识模糊","轻度昏迷","中度昏迷"],"a":2,"e":"意识模糊表现为意识水平轻度下降，能保持简单精神活动，但对时间、地点、人物的定向力发生障碍，较嗜睡为深。A项昏睡需强烈刺激方可唤醒且答话含糊；B项嗜睡可被唤醒并正确回答；D、E项昏迷无论轻重均无觉醒反应，不能唤醒"},{"q":"持续睡眠状态，可被唤醒，唤醒后能正确回答问题和做出各种反应","o":["昏睡","嗜睡","意识模糊","轻度昏迷","中度昏迷"],"a":1,"e":"嗜睡是最轻的意识障碍，为病理性倦睡，患者陷入持续睡眠状态，可被唤醒并能正确回答问题和作出反应，刺激去除后很快再入睡。A项昏睡不易唤醒，需压迫眶上神经等强刺激且答话含糊；C项意识模糊以定向力障碍为主；D、E项昏迷不能被唤醒"},{"q":"脑外伤患者可见","o":["双侧瞳孔扩大","双侧瞳孔缩小","双侧瞳孔大小不等","瞳孔缩小伴眼睑下垂","瞳孔扩大伴眼睑下垂"],"a":2,"e":"双侧瞳孔大小不等常提示颅内病变，脑外伤、脑肿瘤、脑疝等使动眼神经或中脑瞳孔中枢受损，且不等程度可变化不定。A项双侧瞳孔扩大见于青光眼绝对期、视神经萎缩或濒死状态；B项双侧缩小见于吗啡、有机磷中毒；D项瞳孔缩小伴眼睑下垂为Horner综合征；E项瞳孔扩大伴眼睑下垂非脑外伤特征"},{"q":"青光眼患者可见","o":["双侧瞳孔扩大","双侧瞳孔缩小","双侧瞳孔大小不等","瞳孔缩小伴眼睑下垂","瞳孔扩大伴眼睑下垂"],"a":0,"e":"青光眼绝对期因眼压持续升高损害虹膜括约肌及睫状神经节，瞳孔散大呈椭圆形，对光反射迟钝或消失；双侧散大伴对光反射消失为濒死表现。B项双侧瞳孔缩小见于吗啡、毛果芸香碱等药物；C项大小不等提示脑外伤、脑疝等颅内病变；D项为Horner综合征；E项无对应典型疾病"},{"q":"人在兴奋时，可见","o":["双侧瞳孔扩大","双侧瞳孔缩小","双侧瞳孔大小不等","瞳孔缩小伴眼睑下垂","瞳孔扩大伴眼睑下垂"],"a":0,"e":"瞳孔扩大由交感神经支配的瞳孔开大肌收缩所致，生理情况下兴奋、疼痛、暗处均可见瞳孔散大，属正常反应。B项双侧瞳孔缩小见于虹膜炎症、有机磷或吗啡中毒；C项双侧大小不等提示颅内病变如脑外伤、脑疝；D项为Horner综合征的交感麻痹表现；E项无对应情况"},{"q":"Horner综合征时，可见","o":["双侧瞳孔扩大","双侧瞳孔缩小","双侧瞳孔大小不等","瞳孔缩小伴眼睑下垂","瞳孔扩大伴眼睑下垂"],"a":3,"e":"Horner综合征因一侧眼交感神经麻痹，出现同侧瞳孔缩小、上睑下垂、眼球下陷、结膜充血及面部无汗。A项双侧瞳孔大小不等伴对光反射变化多见于脑外伤、中脑损害；B项双侧瞳孔缩小见于吗啡、有机磷中毒；C项一侧瞳孔散大见于一侧动眼神经损伤；E项无对应典型病变"},{"q":"腰背痛，X线片显示腰椎增生、椎体呈楔形改变的疾病是","o":["脊椎结核","椎间盘脱出症","脊柱压缩性骨折","脊柱肿瘤","强直性脊柱炎"],"a":2,"e":"脊柱压缩性骨折多有外伤史或老年骨质疏松基础，椎体被压成楔形，X线示椎体楔形改变及骨质增生，局部棘突压痛、后凸畸形。A项脊椎结核X线以椎体破坏、椎间隙变窄及冷脓肿为主；B项椎间盘脱出症以椎间隙变窄、坐骨神经痛为主，无椎体楔形变；D项脊柱肿瘤以骨质破坏、肿块为主；E项强直性脊柱炎呈竹节样改变"},{"q":"腰背痛，伴左下肢麻木、乏力的疾病是","o":["脊椎结核","椎间盘脱出症","脊柱压缩性骨折","脊柱肿瘤","强直性脊柱炎"],"a":1,"e":"椎间盘突出压迫神经根，引起腰痛伴下肢放射性麻木、乏力，咳嗽喷嚏加重，直腿抬高试验阳性，腰4～骶1最常见。A项脊椎结核多有低热盗汗、椎体破坏；C项压缩性骨折有外伤史及椎体楔形变；D项脊柱肿瘤疼痛夜间明显、进行性加重；E项强直性脊柱炎为青年男性对称性骶髂关节痛与晨僵"},{"q":"腰背痛，X线片显示腰椎增生、椎间盘变窄的疾病是","o":["脊椎结核","椎间盘脱出症","脊柱压缩性骨折","脊柱肿瘤","强直性脊柱炎"],"a":1,"e":"椎间盘退变脱水、纤维环破裂致椎间隙变窄，常伴椎体边缘骨质增生，压迫神经根产生腰背痛及坐骨神经痛，直腿抬高试验可阳性。A项脊椎结核以椎体破坏、椎间隙变窄和全身中毒症状为特点；C项压缩性骨折表现为椎体楔形变；D项脊柱肿瘤以骨质破坏和进行性疼痛为主；E项强直性脊柱炎为竹节样改变"},{"q":"急性胆囊炎时，出现","o":["紫纹","板状腹","腹壁揉面感","墨菲征阳性","Courvoisier征阳性"],"a":3,"e":"墨菲征阳性是急性胆囊炎的特征，检查者按压右肋下胆囊点嘱深吸气，发炎胆囊下移触及手指引起剧痛并致吸气中止。A项紫纹见于皮质醇增多症；B项板状腹为急性弥漫性腹膜炎的腹肌强直；C项腹壁揉面感见于结核性腹膜炎；E项Courvoisier征阳性为胰头癌所致无痛性胆囊肿大"},{"q":"急性弥漫性腹膜炎时，出现","o":["紫纹","板状腹","腹壁揉面感","墨菲征阳性","Courvoisier征阳性"],"a":1,"e":"急性胃肠穿孔或脏器破裂致弥漫性腹膜炎，胃酸、肠液强烈刺激腹膜引起腹肌痉挛，腹壁强直硬如木板，伴压痛反跳痛。A项紫纹为皮质醇增多症的皮肤表现；C项腹壁揉面感见于结核性腹膜炎等慢性病变；D项墨菲征阳性为急性胆囊炎；E项Courvoisier征阳性提示胰头癌胆道梗阻"},{"q":"皮质醇增多症时，出现","o":["紫纹","板状腹","腹壁揉面感","墨菲征阳性","Courvoisier征阳性"],"a":0,"e":"皮质醇增多症因糖皮质激素促进蛋白分解、抑制胶原合成，皮肤变薄，皮下血管显露，在腹部、臀部及股外侧出现紫色条纹，伴向心性肥胖、满月脸、高血压。B项板状腹为急性弥漫性腹膜炎；C项揉面感见于结核性腹膜炎；D项墨菲征阳性为急性胆囊炎；E项Courvoisier征阳性提示胰头癌"},{"q":"结核性腹膜炎时，出现","o":["紫纹","板状腹","腹壁揉面感","墨菲征阳性","Courvoisier征阳性"],"a":2,"e":"结核性腹膜炎或其他慢性腹膜炎症发展缓慢，腹膜增厚并与肠管、肠系膜粘连，触诊腹壁柔韧而有抵抗力、不易压陷，称揉面感，亦可见于腹膜转移癌。B项板状腹见于急性胃肠穿孔所致弥漫性腹膜炎；A项紫纹为皮质醇增多症表现；D项墨菲征阳性为急性胆囊炎；E项Courvoisier征阳性提示胰头癌"},{"q":"视交叉损伤临床表现","o":["单眼视力丧失","双眼颞侧视野缺损","双眼同向偏盲","双眼同向上1/4象限盲","双眼同向下1/4象限盲"],"a":1,"e":"视交叉处来自两眼鼻侧视网膜的纤维交叉，故视交叉中部受损时双颞侧纤维受累，表现为双眼颞侧偏盲，常见于垂体瘤压迫。A项单眼视力丧失见于一侧视神经病变；C项双眼同向偏盲见于视束或枕叶视觉中枢病变；D、E项象限盲多为视辐射部分损伤，不符合交叉部损害"},{"q":"视神经损伤临床表现","o":["单眼视力丧失","双眼颞侧视野缺损","双眼同向偏盲","双眼同向上1/4象限盲","双眼同向下1/4象限盲"],"a":0,"e":"视神经为单眼视觉传入通路，损伤后该眼视力减退或丧失，直接对光反射消失而间接反射存在，单侧不规则视野缺损亦源于视神经或视网膜病变。B项双眼颞侧视野缺损为视交叉中部损伤；C项双眼同向偏盲见于视交叉以后中枢病变；D、E项象限盲为视辐射部分受损"},{"q":"枕叶病变临床表现","o":["单眼视力丧失","双眼颞侧视野缺损","双眼同向偏盲","双眼同向上1/4象限盲","双眼同向下1/4象限盲"],"a":2,"e":"视交叉以后的视束、视辐射及枕叶视觉中枢病变损伤双眼同侧视网膜纤维，产生双眼同向偏盲，枕叶病变尚可不伴黄斑回避。A项单眼视力丧失为视神经病变；B项双眼颞侧偏盲为视交叉中部受损；D、E项同向上、下象限盲分别为视辐射颞叶、顶叶部分损伤"},{"q":"中枢性呼吸困难","o":["端坐呼吸","Kussmaul呼吸","Biot呼吸","叹气样呼吸","呼气时间延长"],"a":2,"e":"Biot呼吸又称间停呼吸，表现为规律呼吸数次后突然停止一段时间再重新开始，因呼吸中枢兴奋性降低、反馈系统失常所致，见于重症颅脑疾病、脑膜炎等中枢性呼吸困难。A项端坐呼吸为左心衰竭肺淤血体位；B项Kussmaul呼吸为代谢性酸中毒深大呼吸；D项叹气样呼吸为功能性；E项呼气延长为小气道阻塞"},{"q":"癔症的呼吸困难","o":["端坐呼吸","Kussmaul呼吸","Biot呼吸","叹气样呼吸","呼气时间延长"],"a":3,"e":"癔症等精神性呼吸困难表现为呼吸快浅，常插入一次深大呼吸并伴叹息声，即叹气样呼吸，多因过度通气导致呼吸性碱中毒，属功能性改变。A项端坐呼吸见于急性左心衰竭；B项Kussmaul呼吸为代谢性酸中毒；C项Biot呼吸提示中枢性呼吸抑制；E项呼气时间延长见于支气管哮喘"},{"q":"哮喘患者的呼吸困难","o":["端坐呼吸","Kussmaul呼吸","Biot呼吸","叹气样呼吸","呼气时间延长"],"a":4,"e":"支气管哮喘时小支气管痉挛、黏膜水肿，呼气气流受限，呼气费力且时间明显延长，常伴呼气期哮鸣音，属呼气性呼吸困难。A项端坐呼吸为急性左心衰竭表现；B项Kussmaul呼吸为酸中毒深大呼吸；C项Biot呼吸为中枢性间停呼吸；D项叹气样呼吸见于癔症、神经衰弱，均非哮喘特征"},{"q":"急性肺水肿的呼吸困难","o":["端坐呼吸","Kussmaul呼吸","Biot呼吸","叹气样呼吸","呼气时间延长"],"a":0,"e":"急性肺水肿时肺毛细血管压骤升、肺淤血严重，平卧使回心血量增多而加重气促，患者被迫端坐位以减少静脉回流、改善通气。B项Kussmaul呼吸为代谢性酸中毒的深大呼吸；C项Biot呼吸为中枢性间停呼吸；D项叹气样呼吸属功能性改变；E项呼气延长为支气管哮喘的小气道阻塞表现"},{"q":"异常纤维蛋白血症时，患者检查结果可显示","o":["APTT正常，PT正常","APTT延长，PT正常","APTT正常，PT延长","APTT延长，PT延长","APTT正常，PT缩短"],"a":3,"e":"异常纤维蛋白原血症时纤维蛋白原结构或功能异常，参与共同凝血途径的纤维蛋白形成障碍，可使PT与APTT均延长，同时TT显著延长。A项两者均正常见于凝血因子ⅩⅢ缺陷；B项APTT延长、PT正常提示内源性途径因子Ⅷ、Ⅸ、Ⅺ、Ⅻ缺陷；C项PT延长、APTT正常为外源性因子Ⅶ缺陷；E项PT缩短无对应意义"},{"q":"获得性ⅩⅢ因子缺乏的患者，检查结果可出现","o":["APTT正常，PT正常","APTT延长，PT正常","APTT正常，PT延长","APTT延长，PT延长","APTT正常，PT缩短"],"a":0,"e":"因子ⅩⅢ为纤维蛋白稳定因子，作用于凝血共同途径末端之后，不参与PT与APTT所反映的凝血活酶形成与纤维蛋白原凝固过程，故缺乏时两项筛检试验均正常，需靠凝块溶解试验诊断。B项提示内源性因子缺乏；C项提示外源性因子Ⅶ缺乏；D项提示共同途径因子Ⅹ、Ⅴ、Ⅱ、Ⅰ缺乏"},{"q":"血友病B的患者，检查结果显示","o":["APTT正常，PT正常","APTT延长，PT正常","APTT正常，PT延长","APTT延长，PT延长","APTT正常，PT缩短"],"a":1,"e":"血友病B为遗传性因子Ⅸ缺乏，因子Ⅸ属内源性凝血途径，故APTT延长而PT正常，临床表现为自发性关节、肌肉出血。A项两者均正常见于ⅩⅢ因子缺陷；C项PT延长、APTT正常为因子Ⅶ缺陷；D项两者均延长提示共同途径因子Ⅹ、Ⅴ、凝血酶原或纤维蛋白原缺陷；E项PT缩短无临床对应"},{"q":"遗传性Ⅶ缺陷症的患者，检查结果显示","o":["APTT正常，PT正常","APTT延长，PT正常","APTT正常，PT延长","APTT延长，PT延长","APTT正常，PT缩短"],"a":2,"e":"因子Ⅶ是外源性凝血途径的启动因子，遗传性Ⅶ缺乏使PT延长而内源性途径不受累，APTT正常，临床可有皮肤黏膜及内脏出血。A项两者均正常见于ⅩⅢ因子缺陷；B项APTT延长、PT正常为内源性因子Ⅷ、Ⅸ、Ⅺ、Ⅻ缺乏；D项两者均延长为共同途径缺陷；E项无对应"},{"q":"糖尿病的眼底","o":["视网膜动脉变细，反光增强","视网膜静脉迂曲扩张，有点、片状深层出血","视网膜血管色淡，视盘边界不清，视网膜上有带白色中心的出血斑及渗出物","视网膜的卵圆形出血斑，中心呈白色","视网膜动脉迂曲扩张"],"a":1,"e":"糖尿病视网膜病变早期可见视网膜静脉扩张迂曲，随病程出现点状、片状深层出血及微血管瘤、渗出，严重者新生血管形成。A项视网膜动脉变细、反光增强为高血压动脉硬化；C项血管色淡、视盘边界不清伴白色中心出血斑为白血病眼底；D项卵圆形中心白色出血斑即Roth斑，见于感染性心内膜炎；E项动脉迂曲扩张无特异对应"},{"q":"高血压的眼底","o":["视网膜动脉变细，反光增强","视网膜静脉迂曲扩张，有点、片状深层出血","视网膜血管色淡，视盘边界不清，视网膜上有带白色中心的出血斑及渗出物","视网膜的卵圆形出血斑，中心呈白色","视网膜动脉迂曲扩张"],"a":0,"e":"高血压动脉硬化期视网膜动脉痉挛、变细、反光增强，出现动静脉交叉压迫，动脉呈铜丝状甚至银丝状，晚期可有火焰状出血及棉絮状渗出。B项静脉迂曲扩张伴深层出血为糖尿病视网膜病变；C项为白血病眼底改变；D项Roth斑见于感染性心内膜炎；E项动脉迂曲扩张并非高血压典型表现"},{"q":"感染性心内膜炎","o":["视网膜动脉变细，反光增强","视网膜静脉迂曲扩张，有点、片状深层出血","视网膜血管色淡，视盘边界不清，视网膜上有带白色中心的出血斑及渗出物","视网膜的卵圆形出血斑，中心呈白色","视网膜动脉迂曲扩张"],"a":3,"e":"感染性心内膜炎时感染性栓子阻塞视网膜小动脉，或免疫复合物性血管炎致出血，形成卵圆形出血斑且中心呈白色，即Roth斑，结膜亦可见散在出血点。A项动脉变细反光增强为高血压动脉硬化；B项静脉迂曲扩张伴深层出血为糖尿病眼底；C项血管色淡、视盘不清伴白色中心出血斑为白血病眼底；E项无对应"},{"q":"白血病","o":["视网膜动脉变细，反光增强","视网膜静脉迂曲扩张，有点、片状深层出血","视网膜血管色淡，视盘边界不清，视网膜上有带白色中心的出血斑及渗出物","视网膜的卵圆形出血斑，中心呈白色","视网膜动脉迂曲扩张"],"a":2,"e":"白血病时贫血使视网膜血管颜色变淡，浸润与颅内压升高致视盘边界不清，视网膜血管曲张并有带白色中心的出血斑及渗出物。A项动脉变细、反光增强属高血压动脉硬化；B项静脉迂曲扩张伴深层出血为糖尿病眼底；D项卵圆形中心白色出血斑为感染性心内膜炎Roth斑；E项无对应病变"},{"q":"严重肺气肿时，出现","o":["扁平胸","漏斗胸","肋间隙膨隆","胸壁压痛","鸡胸"],"a":2,"e":"严重肺气肿或慢性阻塞性肺疾病用力呼气时，肺内气体排出受阻、胸廓保持过度充气，肋间隙膨隆，伴桶状胸及呼气延长。A项扁平胸见于瘦长体型或肺结核等慢性消耗病；B项漏斗胸为先天性胸骨凹陷；D项胸壁压痛见于肋软骨炎、肋骨骨折或白血病；E项鸡胸多为佝偻病后遗"},{"q":"肺结核时，出现","o":["扁平胸","漏斗胸","肋间隙膨隆","胸壁压痛","鸡胸"],"a":0,"e":"扁平胸表现为胸廓前后径不及左右径一半，见于瘦长体型及肺结核等慢性消耗性疾病，常伴锁骨上窝凹陷。C项肋间隙膨隆见于严重肺气肿、张力性气胸或大量胸腔积液用力呼气时；D项胸壁压痛见于肋软骨炎、肋骨骨折及白血病胸骨压痛；B项漏斗胸、E项鸡胸为先天性或佝偻病性胸廓畸形"},{"q":"白血病时，出现","o":["扁平胸","漏斗胸","肋间隙膨隆","胸壁压痛","鸡胸"],"a":3,"e":"白血病骨髓异常增生使胸骨压痛和叩击痛明显，正常胸壁无压痛；此外肋间神经炎、肋软骨炎、胸壁软组织炎及肋骨骨折也可有局部压痛。A项扁平胸见于肺结核或瘦长体型；B项漏斗胸为先天性畸形；C项肋间隙膨隆见于肺气肿、气胸或大量胸腔积液；E项鸡胸多见于佝偻病"},{"q":"自身免疫性肝炎","o":["抗-TG和抗-TM阳性","抗平滑肌抗体阳性","抗线粒体抗体阳性","抗乙酰胆碱受体抗体阳性","抗Jo-1抗体阳性"],"a":1,"e":"抗平滑肌抗体以IgG为主，靶抗原为肌动蛋白，是自身免疫性肝炎的重要血清学标志，尤其F型肌动蛋白相关，也可见于原发性胆汁性肝硬化及急性病毒性肝炎。A项抗-TG、抗-TM阳性为桥本甲状腺炎；C项抗线粒体抗体阳性为原发性胆汁性肝硬化；D项抗乙酰胆碱受体抗体见于重症肌无力；E项抗Jo-1抗体见于多发性肌炎"},{"q":"原发性胆汁性肝硬化","o":["抗-TG和抗-TM阳性","抗平滑肌抗体阳性","抗线粒体抗体阳性","抗乙酰胆碱受体抗体阳性","抗Jo-1抗体阳性"],"a":2,"e":"抗线粒体抗体针对线粒体内外膜蛋白，主要是IgG，是原发性胆汁性肝硬化的特征性自身抗体，敏感性和特异性均高，阴性而疑似者可查抗Sp100抗体。A项抗-TG、抗-TM阳性见于桥本甲状腺炎；B项抗平滑肌抗体阳性见于自身免疫性肝炎；D项抗乙酰胆碱受体抗体提示重症肌无力；E项抗Jo-1抗体见于多发性肌炎"},{"q":"多发性肌炎","o":["抗-TG和抗-TM阳性","抗平滑肌抗体阳性","抗线粒体抗体阳性","抗乙酰胆碱受体抗体阳性","抗Jo-1抗体阳性"],"a":4,"e":"抗Jo-1抗体的靶抗原是组氨酰tRNA合成酶，主要为IgG1，是多发性肌炎的特异性抗体，与肺间质病变、关节炎等构成Jo-1综合征。A项抗-TG、抗-TM阳性为桥本甲状腺炎；B项抗平滑肌抗体阳性为自身免疫性肝炎；C项抗线粒体抗体阳性为原发性胆汁性肝硬化；D项抗乙酰胆碱受体抗体见于重症肌无力"},{"q":"桥本甲状腺炎","o":["抗-TG和抗-TM阳性","抗平滑肌抗体阳性","抗线粒体抗体阳性","抗乙酰胆碱受体抗体阳性","抗Jo-1抗体阳性"],"a":0,"e":"桥本甲状腺炎为自身免疫性甲状腺病，抗甲状腺球蛋白抗体与抗甲状腺微粒体抗体阳性率高，前者60%～70%、后者50%～100%，可伴甲状腺肿大和功能减退。B项抗平滑肌抗体阳性为自身免疫性肝炎；C项抗线粒体抗体阳性为原发性胆汁性肝硬化；D项抗乙酰胆碱受体抗体为重症肌无力；E项抗Jo-1抗体为多发性肌炎"},{"q":"转铁蛋白缺乏症时，可见","o":["血清铁增加，血清铁蛋白增加，总铁结合力升高","血清铁降低，血清铁蛋白降低，总铁结合力升高","血清铁降低，血清铁蛋白降低，总铁结合力降低","血清铁增加，血清铁蛋白降低，总铁结合力降低","血清铁降低，血清铁蛋白增加，总铁结合力降低"],"a":2,"e":"转铁蛋白缺乏时肝脏合成转铁蛋白减少，总铁结合力降低；铁转运障碍使血清铁下降，可供利用的铁不足，铁蛋白亦偏低，需与缺铁性贫血鉴别。B项血清铁、铁蛋白降低而总铁结合力升高是缺铁性贫血的典型表现；E项血清铁降低、铁蛋白增高而总铁结合力降低为慢性病性贫血；A、D项血清铁升高，不符合缺乏状态"},{"q":"缺铁性贫血时，可见","o":["血清铁增加，血清铁蛋白增加，总铁结合力升高","血清铁降低，血清铁蛋白降低，总铁结合力升高","血清铁降低，血清铁蛋白降低，总铁结合力降低","血清铁增加，血清铁蛋白降低，总铁结合力降低","血清铁降低，血清铁蛋白增加，总铁结合力降低"],"a":1,"e":"缺铁性贫血时体内贮存铁耗竭，血清铁蛋白降低，血清铁下降，肝脏代偿性合成转铁蛋白增加使总铁结合力升高，转铁蛋白饱和度下降，属小细胞低色素性贫血。C项总铁结合力降低不符合缺铁，多见于慢性病贫血或转铁蛋白缺乏；E项铁蛋白增高、总铁结合力降低为慢性病性贫血；A、D项血清铁升高，与缺铁不符"},{"q":"慢性病性贫血时，可见","o":["血清铁增加，血清铁蛋白增加，总铁结合力升高","血清铁降低，血清铁蛋白降低，总铁结合力升高","血清铁降低，血清铁蛋白降低，总铁结合力降低","血清铁增加，血清铁蛋白降低，总铁结合力降低","血清铁降低，血清铁蛋白增加，总铁结合力降低"],"a":4,"e":"慢性炎症或肿瘤时铁调素升高，巨噬细胞铁释放受阻，虽有贮存但利用障碍，故血清铁降低、铁蛋白正常或增高，转铁蛋白合成受抑使总铁结合力降低。B项为缺铁性贫血，铁蛋白降低而总铁结合力升高；C项为转铁蛋白缺乏症；A、D项血清铁升高，见于铁负荷过多或溶血，均非慢性病贫血"},{"q":"淋巴瘤","o":["发热伴结膜充血","发热伴昏迷","发热伴寒战","发热伴肝脾大","发热伴皮疹"],"a":3,"e":"淋巴瘤为淋巴系统恶性肿瘤，常有发热、盗汗、消瘦，并因淋巴组织增生浸润出现肝脾肿大和淋巴结肿大。A项发热伴结膜充血见于麻疹、流行性出血热、钩端螺旋体病；B项发热伴昏迷见于中毒性菌痢、流行性脑脊髓膜炎、乙脑；C项发热伴寒战见于大叶性肺炎、败血症、急性胆囊炎；E项伴皮疹见于发疹性传染病"},{"q":"中毒性菌痢","o":["发热伴结膜充血","发热伴昏迷","发热伴寒战","发热伴肝脾大","发热伴皮疹"],"a":1,"e":"中毒性细菌性痢疾多见于儿童，志贺毒素及内毒素引起严重毒血症和感染性休克，常先发热后迅速出现昏迷、惊厥，肠道症状可不明显。A项伴结膜充血见于流行性出血热、麻疹等；C项伴寒战见于大叶性肺炎、败血症、急性胆囊炎；D项伴肝脾大见于淋巴瘤、白血病、疟疾；E项伴皮疹见于出疹性感染"},{"q":"急性胆囊炎","o":["发热伴结膜充血","发热伴昏迷","发热伴寒战","发热伴肝脾大","发热伴皮疹"],"a":2,"e":"急性胆囊炎多由胆石梗阻合并细菌感染引起，胆道感染易出现寒战高热，伴右上腹绞痛、墨菲征阳性及恶心呕吐。A项发热伴结膜充血见于麻疹、流行性出血热、钩端螺旋体病；B项伴昏迷提示中毒性菌痢、乙脑等中枢受累；D项伴肝脾大见于淋巴瘤、白血病；E项伴皮疹见于发疹性传染病"},{"q":"流行性出血热","o":["发热伴结膜充血","发热伴昏迷","发热伴寒战","发热伴肝脾大","发热伴皮疹"],"a":0,"e":"流行性出血热由汉坦病毒感染引起，发热期即有球结膜充血、水肿、出血点，伴三红及肾损害、出血倾向。C项发热伴寒战见于大叶性肺炎、败血症、急性胆囊炎；B项伴昏迷见于中毒性菌痢、乙脑；D项伴肝脾大见于淋巴瘤、白血病、疟疾；E项伴皮疹见于麻疹、猩红热等出疹性疾病"},{"q":"内外源性凝血系统形成凝血活酶时，都需要","o":["因子Ⅻ","因子Ⅷ","因子Ⅹ","因子ⅩⅢ","因子Ⅴ"],"a":2,"e":"内源性与外源性凝血途径分别经Ⅻ、Ⅺ、Ⅸ、Ⅷ及Ⅶ、组织因子激活，最终共同激活因子Ⅹ，Ⅹa与Ⅴa、钙离子、磷脂形成凝血酶原酶复合物，故两途径形成凝血活酶均需因子Ⅹ。A项因子Ⅻ仅参与内源性始动；B项因子Ⅷ为内源性辅因子；D项因子ⅩⅢ稳定纤维蛋白，不参与凝血活酶形成；E项因子Ⅴ为共同途径辅因子"},{"q":"属于维生素K依赖性凝血因子是","o":["因子Ⅻ","因子Ⅷ","因子Ⅹ","因子ⅩⅢ","因子Ⅴ"],"a":2,"e":"维生素K依赖性凝血因子包括Ⅱ、Ⅶ、Ⅸ、Ⅹ，其谷氨酸残基需经维生素K依赖的γ-羧化才能结合钙离子并发挥活性，因子Ⅹ为其中之一。A项因子Ⅻ不依赖维生素K，为内源性始动因子；B项因子Ⅷ由内皮细胞合成，不依赖维生素K；D项因子ⅩⅢ不依赖维生素K；E项因子Ⅴ亦非维生素K依赖性"},{"q":"内源性凝血途径的始动因子是","o":["因子Ⅻ","因子Ⅷ","因子Ⅹ","因子ⅩⅢ","因子Ⅴ"],"a":0,"e":"内源性凝血途径由因子Ⅻ接触带负电荷的胶原、玻璃等表面被激活而启动，继而激活Ⅺ、Ⅸ、Ⅷ，形成内源性凝血活酶，凝血时间试验即反映此过程。B项因子Ⅷ为内源性途径辅因子而非始动因子；C项因子Ⅹ是内、外源途径的共同交汇点；D项因子ⅩⅢ作用于纤维蛋白稳定阶段；E项因子Ⅴ为共同途径辅因子"},{"q":"单侧主支气管不完全阻塞在F/V曲线上的典型表现为","o":["吸气相平台","呼气相平台","吸气相平台＋呼气相平台","双蝶形改变","高位平台"],"a":3,"e":"单侧主支气管不完全阻塞使中央气道在吸气和呼气两相均受限，流量-容积曲线吸、呼气相均出现平台，呈双蝶形改变。A项吸气相平台为胸外型上气道阻塞，吸气时胸腔外气道受压；B项呼气相平台为胸内型上气道阻塞，呼气时胸内压升高压迫气道；E项高位平台非上气道阻塞的典型描述"},{"q":"胸外型上气道阻塞在F/V曲线上的典型表现为","o":["吸气相平台","呼气相平台","吸气相平台＋呼气相平台","双蝶形改变","高位平台"],"a":0,"e":"胸外型上气道阻塞属可变性阻塞，吸气时胸腔内负压使胸腔外气道内压低于外界而进一步塌陷，吸气流量受限，流量-容积曲线吸气相出现平台。B项呼气相平台为胸内型上气道阻塞；C项双蝶形改变为固定性狭窄或单侧主支气管阻塞；D、E项非上气道阻塞的典型曲线"},{"q":"胸内型上气道阻塞在F/V曲线上的典型表现为","o":["吸气相平台","呼气相平台","吸气相平台＋呼气相平台","双蝶形改变","高位平台"],"a":1,"e":"胸内型上气道阻塞时呼气期胸内压升高，压迫胸腔内气道使其进一步狭窄，呼气流量受限，流量-容积曲线呼气相出现平台。A项吸气相平台为胸外型上气道阻塞；C项双蝶形改变为固定性气道狭窄或单侧主支气管不完全阻塞；D、E项不用于描述上气道阻塞的流量容积曲线"},{"q":"固定型上气道阻塞在F/V曲线上的典型表现为","o":["吸气相平台","呼气相平台","吸气相平台＋呼气相平台","双蝶形改变","高位平台"],"a":2,"e":"固定型上气道阻塞（如气管狭窄、肿瘤）使气道管径在吸气和呼气时均固定受限，故流量-容积曲线吸气相与呼气相均出现平台。可变型胸外阻塞（如喉软化）仅吸气相受限呈吸气相平台；可变型胸内阻塞仅呼气相受限呈呼气相平台，均与固定型的双相平台不同"},{"q":"缺铁性贫血时，可见","o":["杵状指","匙状甲","爪形手","尺偏畸形","肢端肥大症"],"a":1,"e":"匙状甲又称反甲，指甲中央凹陷、边缘翘起、变薄粗糙，是缺铁性贫血的特征性指甲改变，与组织缺铁致角化异常有关。A项杵状指见于慢性缺氧性疾病如支气管扩张、肺癌；C项爪形手见于尺神经损伤、进行性肌萎缩；D项尺偏畸形为类风湿关节炎晚期表现；E项肢端肥大症见于垂体嗜酸性细胞瘤"},{"q":"垂体前叶嗜酸性细胞瘤时，可见","o":["杵状指","匙状甲","爪形手","尺偏畸形","肢端肥大症"],"a":4,"e":"垂体前叶嗜酸性细胞瘤分泌过多生长激素，成人骨骺闭合后发病表现为肢端肥大症，头颅增大、下颌前突、眉弓颧骨隆起、唇舌肥厚、手足粗大。A项杵状指为慢性缺氧表现；B项匙状甲见于缺铁性贫血；C项爪形手为尺神经损伤；D项尺偏畸形为类风湿关节炎晚期改变"},{"q":"尺神经损伤时，可见","o":["杵状指","匙状甲","爪形手","尺偏畸形","肢端肥大症"],"a":2,"e":"尺神经支配骨间肌及小鱼际肌，损伤后掌指关节过伸、指间关节屈曲，骨间肌与小鱼际萎缩，手呈鸟爪样，即爪形手。A项杵状指见于支气管扩张、肺癌等慢性缺氧；B项匙状甲为缺铁性贫血；D项尺偏畸形见于类风湿关节炎；E项肢端肥大症为生长激素过多所致"},{"q":"类风湿性关节炎时，可见","o":["杵状指","匙状甲","爪形手","尺偏畸形","肢端肥大症"],"a":3,"e":"类风湿关节炎慢性对称性多关节炎，滑膜增生侵蚀关节软骨与韧带，晚期出现关节畸形，掌指关节尺侧偏斜、天鹅颈或纽扣花样改变，伴晨僵和功能障碍。A项杵状指为慢性缺氧；B项匙状甲为缺铁性贫血；C项爪形手为尺神经损伤；E项肢端肥大症为垂体瘤所致，均非类风湿关节炎畸形"},{"q":"吗啡中毒瞳孔改变","o":["一侧瞳孔正常，一侧瞳孔缩小","双侧瞳孔缩小","一侧瞳孔正常，一侧瞳孔散大","双侧瞳孔散大","双侧瞳孔正常"],"a":1,"e":"吗啡类中毒兴奋动眼神经副交感核，使瞳孔括约肌收缩，双侧瞳孔呈针尖样缩小，常伴呼吸抑制、昏迷，有机磷中毒亦缩小。A项一侧缩小、一侧正常见于Horner综合征；C项一侧散大提示动眼神经损伤或脑疝；D项双侧散大见于阿托品中毒、濒死状态；E项正常瞳孔无中毒意义"},{"q":"Horner综合征瞳孔表现","o":["一侧瞳孔正常，一侧瞳孔缩小","双侧瞳孔缩小","一侧瞳孔正常，一侧瞳孔散大","双侧瞳孔散大","双侧瞳孔正常"],"a":0,"e":"Horner综合征由一侧颈交感神经麻痹引起，表现为同侧瞳孔缩小、上睑下垂、眼球下陷、结膜充血及面部无汗，对侧瞳孔正常。B项双侧瞳孔缩小见于吗啡、有机磷中毒；C项一侧瞳孔散大见于一侧动眼神经损伤；D项双侧散大见于阿托品中毒或濒死；E项双侧正常无定位意义"},{"q":"一侧动眼神经损伤瞳孔表现","o":["一侧瞳孔正常，一侧瞳孔缩小","双侧瞳孔缩小","一侧瞳孔正常，一侧瞳孔散大","双侧瞳孔散大","双侧瞳孔正常"],"a":2,"e":"动眼神经含副交感纤维支配瞳孔括约肌，一侧损伤后该侧瞳孔散大、对光反射消失，伴上睑下垂、眼球外斜，对侧正常。A项一侧缩小、一侧正常为Horner综合征；B项双侧缩小见于吗啡、有机磷中毒；D项双侧散大见于阿托品中毒或濒死状态；E项无瞳孔异常"},{"q":"阿托品中毒瞳孔改变","o":["一侧瞳孔正常，一侧瞳孔缩小","双侧瞳孔缩小","一侧瞳孔正常，一侧瞳孔散大","双侧瞳孔散大","双侧瞳孔正常"],"a":3,"e":"阿托品阻断M胆碱受体，使瞳孔括约肌麻痹、开大肌作用占优，双侧瞳孔散大、对光反射消失，伴皮肤潮红、高热、烦躁及尿潴留。A项一侧缩小、一侧正常为Horner综合征；B项双侧缩小见于吗啡、有机磷中毒；C项一侧散大见于一侧动眼神经损伤；E项双侧正常不符合中毒表现"},{"q":"二尖瓣型面容为","o":["双颊紫红，面色晦暗","头颅增大，面部高长，唇舌肥厚","目光闪烁，双眼突出，兴奋不安","表情淡漠，反应迟钝","面色苍白，双睑颜面水肿"],"a":0,"e":"二尖瓣面容表现为面色晦暗、双颊紫红、口唇轻度发绀，见于风湿性心脏病二尖瓣狭窄，因肺淤血与周围血管收缩所致。B项头颅增大、面部高长、唇舌肥厚为肢端肥大症面容；C项目光闪烁、眼球突出为甲亢面容；D项表情淡漠、反应迟钝为伤寒面容或黏液性水肿面容；E项面色苍白、双睑水肿为肾病面容"},{"q":"甲亢面容为","o":["双颊紫红，面色晦暗","头颅增大，面部高长，唇舌肥厚","目光闪烁，双眼突出，兴奋不安","表情淡漠，反应迟钝","面色苍白，双睑颜面水肿"],"a":2,"e":"甲亢面容表现为面容惊愕、眼裂增宽、眼球突出、目光炯炯、兴奋不安、烦躁易怒，因甲状腺激素过多致交感兴奋及眼眶组织增生。A项双颊紫红、面色晦暗为二尖瓣面容；B项头颅增大、唇舌肥厚为肢端肥大症面容；D项表情淡漠、反应迟钝为伤寒或黏液性水肿面容；E项面色苍白、眼睑水肿为肾病面容"},{"q":"肾病面容为","o":["双颊紫红，面色晦暗","头颅增大，面部高长，唇舌肥厚","目光闪烁，双眼突出，兴奋不安","表情淡漠，反应迟钝","面色苍白，双睑颜面水肿"],"a":4,"e":"肾病面容表现为面色苍白、眼睑及颜面水肿、舌淡且舌缘有齿痕，因低蛋白血症、水钠潴留及贫血所致。A项双颊紫红、面色晦暗为二尖瓣面容；B项头颅增大、面部高长、唇舌肥厚为肢端肥大症面容；C项目光闪烁、眼球突出为甲亢面容；D项表情淡漠、反应迟钝为伤寒或黏液性水肿面容"},{"q":"尿液中混有淋巴液而呈稀牛奶状，称为","o":["乳糜尿","镜下血尿","血红蛋白尿","胆红素尿","结晶尿"],"a":0,"e":"乳糜尿因淋巴管阻塞或破裂，乳糜液混入尿液，呈乳白色稀牛奶状，静置分层，常见于丝虫病及肾周围淋巴管梗阻，乳糜试验阳性可查见微丝蚴。B项镜下血尿仅镜下见红细胞，尿色正常；C项血红蛋白尿呈暗红或酱油色，隐血阳性；D项胆红素尿呈深黄色、泡沫黄染；E项结晶尿为盐类析出，加热或加酸后浑浊消失"},{"q":"尿液外观呈白色浑浊，加热后浑浊消失，此尿液称为","o":["乳糜尿","镜下血尿","血红蛋白尿","胆红素尿","结晶尿"],"a":4,"e":"结晶尿因尿中磷酸盐、碳酸盐、尿酸盐等盐类浓度过高析出，呈黄白或灰白色浑浊，加热或加酸后浑浊消失，一般无临床意义。A项乳糜尿为乳白色乳状浑浊，乳糜试验阳性，加热不消失；C项血红蛋白尿呈暗红或酱油色；D项胆红素尿深黄色且泡沫黄染；B项镜下血尿外观无明显浑浊"},{"q":"尿液外观呈黄色，震荡后产生的泡沫也呈黄色，此尿液称为","o":["乳糜尿","镜下血尿","血红蛋白尿","胆红素尿","结晶尿"],"a":3,"e":"胆红素尿含大量结合胆红素，外观呈深黄色豆油样，振荡后泡沫仍呈黄色，胆红素定性阳性，见于胆汁淤积性黄疸及肝细胞性黄疸，放置过久可氧化为胆绿素呈棕绿色。A项乳糜尿为乳白色；C项血红蛋白尿呈暗红或酱油色，隐血阳性；E项结晶尿加热后浑浊消失；B项镜下血尿色正常"},{"q":"尿中游离血红蛋白量异常，隐血试验阳性的尿液称为","o":["乳糜尿","镜下血尿","血红蛋白尿","胆红素尿","结晶尿"],"a":2,"e":"血红蛋白尿因血管内溶血使游离血红蛋白经尿排出，尿呈暗红、棕红甚至酱油色，隐血试验阳性而镜下红细胞不多，见于蚕豆病、阵发性睡眠性血红蛋白尿症、血型不合输血反应等。A项乳糜尿呈乳白色，乳糜试验阳性；B项镜下血尿镜检红细胞增多；D项胆红素尿呈深黄色、泡沫黄染；E项结晶尿加热后浑浊消失"},{"q":"肾盂肾炎见","o":["尿频、尿急伴有血尿，午后低热，乏力盗汗","尿频、尿急和尿痛，伴会阴、腹股沟和睾丸胀痛","尿频、尿急和尿痛，伴有尿流突然中断","尿频伴多饮、多尿和口渴，但无尿急和尿痛","尿频、尿急和尿痛症状不剧烈，但伴有双侧腰痛"],"a":4,"e":"肾盂肾炎为累及肾盂与肾实质的感染，膀胱刺激征存在但不剧烈，伴双侧腰痛、高热、畏寒及肾区叩击痛，尿中可见白细胞管型。A项伴血尿、午后低热、乏力盗汗见于膀胱结核；B项伴会阴、腹股沟、睾丸胀痛为急性前列腺炎；C项伴尿流突然中断见于膀胱或尿道结石；D项伴多饮多尿口渴无尿急尿痛见于糖尿病、尿崩症"},{"q":"急性前列腺炎见","o":["尿频、尿急伴有血尿，午后低热，乏力盗汗","尿频、尿急和尿痛，伴会阴、腹股沟和睾丸胀痛","尿频、尿急和尿痛，伴有尿流突然中断","尿频伴多饮、多尿和口渴，但无尿急和尿痛","尿频、尿急和尿痛症状不剧烈，但伴有双侧腰痛"],"a":1,"e":"急性前列腺炎除尿频、尿急、尿痛外，炎症波及会阴部，出现会阴、腹股沟及睾丸胀痛，伴发热、寒战，直肠指检前列腺肿大压痛。A项伴血尿、午后低热、盗汗为膀胱结核；C项伴尿流突然中断为膀胱结石嵌顿；D项伴多饮多尿口渴无尿痛为糖尿病或尿崩症；E项伴双侧腰痛为肾盂肾炎"},{"q":"Ⅱ型肾小管酸中毒是","o":["远端肾小管分泌氢离子功能障碍","近端肾小管分泌氢离子功能障碍","远端肾小管重吸收碳酸氢根离子功能障碍","近端肾小管重吸收碳酸氢根离子功能障碍","远端肾小管分泌氢离子或重吸收碳酸氢根离子功能障碍"],"a":2,"e":"官方答案为【远端肾小管重吸收碳酸氢根离子功能障碍】，但依据教材，正确答案为【近端肾小管重吸收碳酸氢根离子功能障碍】。肾小管性酸中毒源于泌氢或重吸收碳酸氢根障碍；滤过碳酸氢根85%～90%由近端肾小管重吸收，Ⅱ型即近端型，缺陷在近端重吸收，Ⅰ型才是远端泌氢障碍。远端仅重吸收10%～15%，原答案混淆了两型"},{"q":"Ⅰ型肾小管酸中毒是","o":["远端肾小管分泌氢离子功能障碍","近端肾小管分泌氢离子功能障碍","远端肾小管重吸收碳酸氢根离子功能障碍","近端肾小管重吸收碳酸氢根离子功能障碍","远端肾小管分泌氢离子或重吸收碳酸氢根离子功能障碍"],"a":0,"e":"Ⅰ型肾小管酸中毒即远端型，远端肾小管主动分泌氢离子障碍，尿液不能酸化，氯化铵负荷试验阳性可协助诊断，临床有高氯性酸中毒、低钾及肾结石。B项近端泌氢障碍不是分型依据；C项远端重吸收碳酸氢根障碍并非Ⅰ型机制；D项近端重吸收碳酸氢根障碍属Ⅱ型；E项为总论定义而非Ⅰ型的特异机制"},{"q":"胃癌腹内广泛转移的表现","o":["全腹紧张度减低","板状腹","柔韧感","蛙腹","舟状腹"],"a":2,"e":"胃癌腹膜广泛转移时腹膜受慢性刺激增厚，并与肠管、肠系膜粘连，触诊腹壁柔韧而有抵抗力、不易压陷，称柔韧感，亦可见于结核性腹膜炎。A项全腹紧张度减低见于慢性消耗、腹壁松弛；B项板状腹为急性胃肠穿孔致弥漫性腹膜炎；D项蛙腹见于大量腹水；E项舟状腹见于恶病质、严重消瘦"},{"q":"十二指肠球部溃疡穿孔的表现","o":["全腹紧张度减低","板状腹","柔韧感","蛙腹","舟状腹"],"a":1,"e":"十二指肠球部溃疡穿孔后肠液、胆汁及胃酸流入腹腔，强烈刺激腹膜引起急性弥漫性腹膜炎，腹肌痉挛强直硬如木板，伴剧烈腹痛及压痛反跳痛。A项全腹紧张度减低见于腹壁松弛或恶病质；C项柔韧感为结核性腹膜炎或癌性腹膜炎的慢性粘连；D项蛙腹见于大量腹水；E项舟状腹见于严重消瘦"},{"q":"大量腹水","o":["肠鸣音亢进","肠鸣音减弱","液波震颤","墨菲征阳性","肾区叩击痛阳性"],"a":2,"e":"腹腔内大量游离液体时，叩击一侧腹部可感到液波震颤，常伴移动性浊音、腹部膨隆呈蛙腹及脐疝。A项肠鸣音亢进见于机械性肠梗阻；B项肠鸣音减弱见于麻痹性肠梗阻或腹膜炎；D项墨菲征阳性为急性胆囊炎；E项肾区叩击痛阳性见于肾盂肾炎、肾结石等肾脏病变"},{"q":"肾盂肾炎","o":["肠鸣音亢进","肠鸣音减弱","液波震颤","墨菲征阳性","肾区叩击痛阳性"],"a":4,"e":"肾盂肾炎属肾脏病变，肋脊角（肾区）叩击痛是其重要体征，检查时左手掌平放肾区、右手叩击，正常无叩击痛，炎症时出现不同程度叩击痛。墨菲征阳性实为胆囊炎的体征，反映胆囊区病变；液波震颤提示大量腹水；肠鸣音亢进或减弱均为肠道动力或梗阻的表现，与肾脏无关"},{"q":"尿潴留患者做尿细菌培养的最佳标本是","o":["随机尿","导管尿","尿三杯试验","中段尿","24h尿"],"a":1,"e":"尿潴留者无法主动排出足够尿液，留取尿液细菌培养应在无菌操作下经导尿管采集导管尿，避免污染。清洁中段尿虽为常规培养首选标本，但尿潴留患者难以留取，故不适用；随机尿易受外阴污染；24h尿多用于蛋白或激素定量；尿三杯试验用于血尿定位，均非培养标本"},{"q":"测定微量清蛋白排泄率的标本推荐用","o":["随机尿","导管尿","尿三杯试验","中段尿","24h尿"],"a":4,"e":"微量清蛋白排泄率反映单位时间内尿中清蛋白排出量，需以24小时尿定量测定，可避免随机尿浓缩稀释带来的误差，与教材以24h尿为参考的定量方式一致。随机尿浓度波动大，仅宜作筛查；导管尿用于尿潴留者培养；尿三杯试验用于血尿分段定位；中段尿常用于常规培养"},{"q":"先天性斜颈可见","o":["头不能抬起","头部向一侧偏斜","颈部强直","头部活动自如","颈部运动受限并伴有疼痛"],"a":1,"e":"斜颈即头部向一侧偏斜，先天性斜颈因胸锁乳突肌挛缩变短所致，复正头位时病侧胸锁乳突肌胸骨端立即隆起，为特征性表现。头不能抬起见于进行性肌营养不良或重症肌无力；颈部强直是脑膜受刺激的表现，见于脑膜炎、蛛网膜下腔出血；颈部运动受限伴疼痛为软组织炎症或颈椎病变"},{"q":"颈椎结核可见","o":["头不能抬起","头部向一侧偏斜","颈部强直","头部活动自如","颈部运动受限并伴有疼痛"],"a":4,"e":"颈部运动受限并伴疼痛见于颈椎结核、软组织炎症、颈肌扭伤及肥大性脊椎炎等，因局部炎性刺激与骨质破坏使转头、屈伸受限且疼痛。颈部强直为脑膜刺激征，见于脑膜炎与蛛网膜下腔出血，并非颈椎结核表现；头部向一侧偏斜是斜颈体征；头部活动自如属正常；头不能抬起提示肌无力"},{"q":"呕吐伴眩晕、眼球震颤见于","o":["幽门梗阻","颅内高压","早孕","迷路炎","细菌性食物中毒"],"a":3,"e":"迷路炎多为中耳炎并发症，炎症破坏迷路骨壁，以发作性眩晕、耳鸣、听力减退及眼球震颤为主要特点，前庭刺激经神经反射引发呕吐。幽门梗阻呕吐多为宿食，伴上腹振水音；颅内高压呈喷射性呕吐伴头痛；早孕呕吐与妊娠相关；细菌性食物中毒以腹痛腹泻为主"},{"q":"呕吐伴瞳孔改变见于","o":["幽门梗阻","颅内高压","早孕","迷路炎","细菌性食物中毒"],"a":4,"e":"细菌性食物中毒中肉毒杆菌毒素可阻断神经肌肉接头，出现瞳孔散大、眼肌麻痹等瞳孔改变，故伴瞳孔改变的呕吐应考虑此类中毒。迷路炎伴眩晕与眼球震颤；颅内高压为喷射性呕吐伴头痛、视乳头水肿；幽门梗阻呕吐宿食；早孕有停经史，均无瞳孔改变"},{"q":"短期内输入大量库存血可导致","o":["高磷血症","高钾血症","低镁血症","低钙血症","高钠血症"],"a":1,"e":"库存血在保存过程中红细胞内钾逐渐外移至血浆，短时间内大量输入可使血钾急剧升高，属摄入过多所致高钾血症。低钙血症虽也可因枸橼酸钠抗凝剂结合钙见于大量输血，但库存血最突出的电解质紊乱是高钾；高磷、高钠并非库存血输入的特征；低镁血症与此无关"},{"q":"佝偻病患儿血电解质检查表现为","o":["高磷血症","高钾血症","低镁血症","低钙血症","高钠血症"],"a":3,"e":"佝偻病因维生素D缺乏致钙吸收减少，钙磷代谢紊乱，血钙降低，可出现手足搐搦，属吸收减少所致低钙血症。高磷血症多见于肾衰竭或甲状旁腺功能减退；高钾血症常见于输入库存血或肾衰竭；低镁血症与营养不良或吸收障碍相关；高钠血症多为脱水或钠摄入过多"},{"q":"焦虑症的核心症状是","o":["情绪低落","快感缺失","运动迟缓","过度担心","肌肉紧张"],"a":3,"e":"焦虑症的精神病理核心是过度担心，即对尚未发生或难以预料的危险与不幸事件产生与现实不相称的担忧，属预期性焦虑，并常伴自主神经症状与运动性不安。紧张不安项与警觉性增高项为焦虑的常见伴随表现；胸闷气短项属自主神经反应；睡眠困难项为继发症状，均非核心特征"},{"q":"抑郁症的主要特征是","o":["情绪低落","快感缺失","运动迟缓","过度担心","肌肉紧张"],"a":0,"e":"抑郁是以显著而持久的情绪低落为主要特征的综合征，核心症状还包括兴趣缺乏与快感缺失，可伴自杀观念。快感缺失虽属核心症状，但并非首要特征描述；运动迟缓是抑郁的躯体表现之一；过度担心与肌肉紧张是焦虑症的主要表现，不属于抑郁的主导症状"},{"q":"粪便中嗜酸性粒细胞增多，可见于哪种疾病","o":["阿米巴痢疾","细菌性痢疾","胆结石","直肠癌","假膜性肠炎"],"a":0,"e":"粪便中嗜酸性粒细胞增多见于阿米巴痢疾及肠道寄生虫感染、过敏性肠病，阿米巴痢疾粪便呈暗红色果酱样，镜检可见大量变性红细胞。细菌性痢疾以中性粒细胞增多为主，红细胞少于白细胞；胆结石不影响粪便细胞；直肠癌多为便血或黏液血便；假膜性肠炎见黏液脓血便"},{"q":"细条样便多见于","o":["阿米巴痢疾","细菌性痢疾","胆结石","直肠癌","假膜性肠炎"],"a":3,"e":"细条样便因直肠或肛门狭窄使粪便通过受阻、形状变细，直肠癌肿块浸润致肠腔狭窄是其常见原因，粪便还可带血及黏液。阿米巴痢疾为果酱样便，细菌性痢疾为黏液脓血便；胆结石不影响大便形状；假膜性肠炎排出黏液脓血便，均不呈细条状"},{"q":"正常空腹血糖值是","o":["1.9～2.8mmol/L","2.9～3.8mmol/L","3.9～6.1mmol/L","6.2～8.4mmol/L","8.4～10.1mmol/L"],"a":2,"e":"成人空腹血浆葡萄糖参考区间为3.9～6.1mmol/L，空腹血糖在此范围内且OGTT 2小时血糖低于7.8mmol/L属正常。1.9～2.8mmol/L已达低血糖水平；2.9～3.8mmol/L偏低；6.2～8.4mmol/L及8.4～10.1mmol/L均高于正常上限，提示血糖升高或糖尿病"},{"q":"低血糖症的血糖值是","o":["1.9～2.8mmol/L","2.9～3.8mmol/L","3.9～6.1mmol/L","6.2～8.4mmol/L","8.4～10.1mmol/L"],"a":0,"e":"低血糖症指血糖低于2.8mmol/L，可出现心慌、出汗、饥饿乃至意识障碍，选项中1.9～2.8mmol/L符合该界限。3.9～6.1mmol/L为正常空腹血糖；2.9～3.8mmol/L虽低于正常但未达低血糖症标准，3.9mmol/L仅是糖尿病治疗监测的干预阈值；6.2mmol/L以上为高血糖"},{"q":"有抗动脉粥样硬化作用的是","o":["总胆固醇增高","三酰甘油增高","高密度脂蛋白增高","低密度脂蛋白增高","脂蛋白a增高"],"a":2,"e":"HDL是颗粒密度最大的脂蛋白，能促进外周组织胆固醇清除并转运至肝代谢，被认为是抗动脉粥样硬化因子，其水平增高有保护作用。LDL富含胆固醇，是动脉粥样硬化的危险因素；总胆固醇及三酰甘油增高均促进粥样硬化；脂蛋白a增高为独立危险因素，均无保护作用"},{"q":"主要存在于前B-脂蛋白和乳糜颗粒中的是","o":["总胆固醇增高","三酰甘油增高","高密度脂蛋白增高","低密度脂蛋白增高","脂蛋白a增高"],"a":1,"e":"三酰甘油是机体恒定的供能物质，主要存在于前β-脂蛋白（极低密度脂蛋白）和乳糜微粒中，参与胆固醇及胆固醇酯的合成，故这两类脂蛋白增高主要体现为血三酰甘油升高。HDL与LDL主要转运胆固醇；总胆固醇增高反映胆固醇代谢异常；脂蛋白a的脂质成分与LDL相似"},{"q":"作为动脉粥样硬化的独立危险因素的是","o":["总胆固醇增高","三酰甘油增高","高密度脂蛋白增高","低密度脂蛋白增高","脂蛋白a增高"],"a":4,"e":"脂蛋白a水平主要由遗传决定，基本不受性别、饮食及环境影响，是动脉粥样硬化的独立危险因子，与冠心病、心肌梗死及介入后再狭窄密切相关。LDL虽是动脉粥样硬化危险因素，但教材强调的独立危险因子特指脂蛋白a；总胆固醇、三酰甘油增高为危险因素而非独立因子；HDL增高反而有保护作用"},{"q":"膀胱颈部出血时，表现为","o":["三杯试验第一杯为血尿","三杯试验第二杯血尿","三杯试验第三杯血尿","全程血尿","尿棕红色镜检无红细胞"],"a":2,"e":"尿三杯试验中终末段（第三杯）血尿提示出血部位在膀胱颈部、三角区或后尿道的前列腺与精囊腺，膀胱颈部出血时血液集中于排尿终末。第一杯血尿提示病变在尿道；第二杯血尿意义有限；全程血尿提示出血来自肾脏或输尿管；尿棕红色镜检无红细胞为血红蛋白尿或卟啉尿"},{"q":"溶血致血红蛋白尿时，表现为","o":["三杯试验第一杯为血尿","三杯试验第二杯血尿","三杯试验第三杯血尿","全程血尿","尿棕红色镜检无红细胞"],"a":4,"e":"溶血时大量红细胞破坏，血红蛋白经肾小球滤过形成血红蛋白尿，尿液呈暗红、棕红甚至酱油色，但因红细胞已溶解，镜检无红细胞或仅少量。三杯试验的血尿均镜检可见红细胞，第一杯提示尿道病变，第三杯提示膀胱颈部出血，全程血尿提示肾或输尿管出血"},{"q":"为速发变态反应所致的是","o":["斑疹","丘疹","玫瑰疹","斑丘疹","荨麻疹"],"a":4,"e":"荨麻疹为稍隆起皮面的苍白色或红色局限性水肿，由速发性皮肤变态反应所致，见于各种过敏反应，消退迅速且不留痕迹。斑疹为局部皮肤发红不凸起，见于斑疹伤寒、丹毒；丘疹凸起皮面，见于药物疹、麻疹；玫瑰疹为伤寒特征；斑丘疹为丘疹周围有红晕底盘"},{"q":"伤寒和副伤寒特征性皮疹是","o":["斑疹","丘疹","玫瑰疹","斑丘疹","荨麻疹"],"a":2,"e":"玫瑰疹为鲜红色圆形斑疹，直径2～3mm，系病灶周围血管扩张所致，压之褪色、松开复现，多见于胸腹部，是伤寒与副伤寒的特征性皮疹。斑疹不凸出皮面，见于斑疹伤寒、丹毒；丘疹凸起皮面，见于药物疹、麻疹；斑丘疹为丘疹伴红晕底盘；荨麻疹由变态反应所致"},{"q":"膝关节积液可有","o":["膝外伤","膝内翻","膝反张","肌萎缩","膝关节匀称性肿胀，双侧膝眼消失并突出"],"a":4,"e":"膝关节积液时关节腔充满液体，表现为膝关节匀称性胀大、双侧膝眼消失并突出，髌上囊积液时髌骨上方明显隆起。膝外伤多有明确外伤史；膝内翻为O形腿，见于佝偻病；膝反张为膝关节过度后伸，见于小儿麻痹后遗症、膝关节结核；肌萎缩为肌肉容积减小"},{"q":"膝关节结核可有","o":["膝外伤","膝内翻","膝反张","肌萎缩","膝关节匀称性肿胀，双侧膝眼消失并突出"],"a":2,"e":"膝反张是膝关节过度后伸形成向前反屈的畸形，见于小儿麻痹后遗症与膝关节结核，结核破坏关节结构及周围软组织致关节稳定性丧失。膝内翻为双下肢O形，见于佝偻病；膝关节匀称性肿胀、膝眼消失为关节积液；膝外伤有外伤史；肌萎缩为废用性改变，均非结核特征"},{"q":"肥厚梗阻性心肌病时，可见","o":["左下肢足背动脉搏动消失","脉搏节律规则强弱交替","脉搏骤起骤落，如潮水涨落","吸气时脉搏明显减弱","正常重搏波增大，一次心搏引起脉搏好似2次"],"a":4,"e":"肥厚型梗阻性心肌病左室流出道梗阻，动脉脉搏可呈双峰，重搏波增大，一次心搏似触及两次搏动。水冲脉骤起骤落，见于主动脉瓣关闭不全、甲亢、动脉导管未闭；奇脉为吸气时脉搏明显减弱，见于心包积液、缩窄性心包炎；交替脉节律规则而强弱交替，提示心肌损害；足背动脉搏动消失见于下肢动脉闭塞"},{"q":"伤寒高热期时，可见","o":["左下肢足背动脉搏动消失","脉搏节律规则强弱交替","脉搏骤起骤落，如潮水涨落","吸气时脉搏明显减弱","正常重搏波增大，一次心搏引起脉搏好似2次"],"a":2,"e":"官方答案为【脉搏骤起骤落，如潮水涨落】，但依据教材，正确答案为【正常重搏波增大，一次心搏引起脉搏好似2次】。伤寒极期持续高热，内毒素使周围血管张力降低，重搏波增大可触及，形成重搏脉，常伴相对缓脉；水冲脉骤起骤落实为主动脉瓣关闭不全、甲亢、动脉导管未闭的体征。奇脉见于心包积液，交替脉提示心肌损害，足背动脉消失为下肢动脉闭塞"},{"q":"患者，男，30岁。反复餐后半小时出现上腹疼痛5年，今晨中上腹剧痛后，转为全腹持续性剧痛3小时，伴恶心和呕吐。患者的腹部体征是","o":["蛙腹","尖腹","球状腹","板状腹","舟状腹"],"a":3,"e":"患者节律性上腹痛多年，突发剧痛转为全腹持续性剧痛，提示胃十二指肠溃疡穿孔，胃酸强烈刺激腹膜致腹肌强烈收缩，形成板状腹，伴明显压痛与反跳痛。蛙腹见于大量腹水；尖腹多见于结核性腹膜炎；球状腹为肠胀气或幽门梗阻；舟状腹见于结核、肿瘤等慢性消耗性恶病质"},{"q":"患者，男，50岁。低热、盗汗伴食欲缺乏、乏力，反复咳嗽、咯血痰1年。患者的腹部体征是","o":["蛙腹","尖腹","球状腹","板状腹","舟状腹"],"a":4,"e":"患者低热、盗汗、乏力、咯血一年，符合结核病慢性消耗表现，严重消瘦时前腹壁凹陷贴近脊柱，肋弓与耻骨联合显露，形成舟状腹。板状腹为急性弥漫性腹膜炎的腹肌强直；蛙腹见于大量腹腔积液；尖腹多见于结核性腹膜炎；球状腹为胃肠胀气或幽门梗阻所致"},{"q":"膀胱颈部结石最常见的症状是","o":["排尿困难伴下腹部绞痛","进行性排尿困难伴无痛性血尿","排尿困难伴低血钾","排尿困难合并周围神经受损","排尿困难伴尿频、尿急、排尿淋漓不尽"],"a":0,"e":"膀胱颈部结石在排尿困难出现前先有下腹部绞痛，疼痛向大腿及会阴放射，排尿时结石嵌顿致尿流受阻，疼痛当时或之后出现血尿。进行性排尿困难伴无痛性血尿是膀胱肿瘤特点；排尿困难伴低血钾见周期性瘫痪等；合并周围神经受损提示脊髓病变；尿频尿急、排尿淋漓不尽见于前列腺增生"},{"q":"膀胱肿瘤最常见的症状是","o":["排尿困难伴下腹部绞痛","进行性排尿困难伴无痛性血尿","排尿困难伴低血钾","排尿困难合并周围神经受损","排尿困难伴尿频、尿急、排尿淋漓不尽"],"a":1,"e":"膀胱肿瘤排尿困难逐渐加重，病程较长，无痛性肉眼或镜下血尿是其特点，膀胱镜下活检可确诊，故进行性排尿困难伴无痛性血尿最符合。伴下腹绞痛并向会阴放射为膀胱颈部结石；低血钾与膀胱肿瘤无关；周围神经受损提示脊髓病变；尿频尿急、尿末淋漓不尽多见于前列腺增生"},{"q":"大便潜血阳性，消化道出血量至少达","o":["5ml","10ml","50ml","400ml","800ml"],"a":0,"e":"消化道出血量每日达5ml以上时，大便隐血试验即可呈阳性，肉眼外观仍正常，是判断少量出血最敏感的指标。10ml无特异界限；50ml以上才出现柏油样黑便；400ml可出现呕血、黑便及全身症状；800ml以上常伴休克等循环障碍表现"},{"q":"出现柏油样便，消化道出血量至少达","o":["5ml","10ml","50ml","400ml","800ml"],"a":2,"e":"上消化道出血量达50ml以上时，血液在肠道内经胃酸与肠液作用，血红蛋白中的铁转变为硫化铁，使粪便呈黑色柏油样，故出现柏油样便至少需50ml。5ml仅使隐血试验阳性；10ml不足以形成黑便；400ml、800ml出血量已属大量出血，可伴呕血或休克"},{"q":"肺气肿叩诊音为","o":["过清音","实音","鼓音","空瓮音","浊音"],"a":0,"e":"肺气肿时肺泡含气量增多、肺泡壁弹性减退，叩诊呈过清音，较清音更响亮、音调更低、时限更长，为肺气肿的典型叩诊音。实音为大量胸腔积液或肺实变；鼓音见于气胸、肺空洞或气腹；空瓮音为张力性气胸或巨大浅表空洞的金属回响；浊音见于心肝被肺覆盖处或肺炎"},{"q":"气胸叩诊音为","o":["过清音","实音","鼓音","空瓮音","浊音"],"a":2,"e":"气胸时胸膜腔积聚气体，叩诊病侧呈鼓音，若空洞巨大、位置表浅或张力性气胸可带金属回响称空瓮音。过清音为肺气肿的叩诊表现，含气量增加但无胸膜腔积气；实音见于大量胸腔积液或肺实变；浊音见于肺炎或心肝被肺覆盖区域"},{"q":"急性呼吸道阻塞性疾病出现","o":["发绀伴红细胞增多","发绀伴心脏瓣膜显著杂音","发绀伴意识障碍和衰竭","发绀伴杵状指（趾）","发绀伴呼吸困难"],"a":4,"e":"急性呼吸道阻塞时气流进出受阻，通气不足致动脉血氧下降，出现发绀并伴明显呼吸困难，如气管异物或肿瘤引起的吸气性呼吸困难。伴杵状指多见于发绀型先心病及慢性肺脓肿、支气管扩张；伴意识障碍见于肺性脑病或休克；伴红细胞增多为慢性缺氧；伴瓣膜杂音提示心脏瓣膜病"},{"q":"慢性脓胸出现","o":["发绀伴红细胞增多","发绀伴心脏瓣膜显著杂音","发绀伴意识障碍和衰竭","发绀伴杵状指（趾）","发绀伴呼吸困难"],"a":3,"e":"慢性脓胸等慢性肺部化脓性疾病长期缺氧，可致发绀伴杵状指（趾），因慢性缺氧使指端毛细血管扩张与结缔组织增生。伴呼吸困难常见于急性呼吸道梗阻、大量气胸等重症；伴意识障碍见于肺性脑病或中毒；伴心脏瓣膜显著杂音提示瓣膜病；红细胞增多为长期缺氧的代偿表现"},{"q":"患者，男，42岁。实验室检查：空腹血糖5.3mmol/L，口服葡萄糖耐量试验的餐后2小时血糖8.9mmol/L。可能的诊断为","o":["1型糖尿病","2型糖尿病","糖耐量减低","糖耐量受损","糖耐量正常"],"a":2,"e":"空腹血糖5.3mmol/L未达糖尿病标准，OGTT 2小时血糖8.9mmol/L落在7.8～11.1mmol/L区间，符合糖耐量减低的判断。1型与2型糖尿病需空腹血糖≥7.0mmol/L或2小时血糖≥11.1mmol/L，本例未达到；糖耐量正常者2小时血糖应低于7.8mmol/L，本例已升高"},{"q":"患者，女，30岁，糖耐量试验结果为空腹5.0mmol/L，1小时7.6mmol/L，2小时7.0mmol/L，3小时5.4mmol/L，尿糖（－）。可能的诊断为","o":["1型糖尿病","2型糖尿病","糖耐量减低","糖耐量受损","糖耐量正常"],"a":4,"e":"空腹5.0mmol/L、餐后1小时7.6mmol/L、2小时7.0mmol/L、3小时5.4mmol/L，各时点血糖均在正常范围，2小时血糖低于7.8mmol/L，尿糖阴性，属糖耐量正常。糖耐量减低需2小时血糖介于7.8～11.1mmol/L且高峰延迟；糖尿病的空腹或2小时血糖达到诊断阈值，本例均未满足"},{"q":"前列腺肿大、质硬，表面有硬结节，最可能的诊断为","o":["正常前列腺","良性前列腺肥大","急性前列腺炎","前列腺癌","常继发精囊结核"],"a":3,"e":"直肠指诊前列腺肿大、质硬、无压痛且表面有硬结节，是前列腺癌的典型表现，质地坚硬与结节形成是鉴别要点。良性前列腺肥大表面光滑有韧感、正中沟消失、无压痛；急性前列腺炎肿大伴明显压痛；正常前列腺大小质地均匀；精囊结核表现为精囊结节状肿胀，常继发于前列腺结核"},{"q":"前列腺肿大，中央沟消失，表面光滑，无压痛及粘连，最可能的诊断为","o":["正常前列腺","良性前列腺肥大","急性前列腺炎","前列腺癌","常继发精囊结核"],"a":1,"e":"前列腺肿大、中央沟（正中沟）消失、表面光滑、无压痛及粘连，多见于老年男性，为良性前列腺肥大的典型指诊表现。前列腺癌质硬且表面有硬结节；急性前列腺炎肿大伴明显压痛；正常前列腺体积正常、正中沟存在；精囊病变表现为精囊条索状或结节状改变"},{"q":"肾衰竭代偿期","o":["Ccr 50～20ml/min","Ccr 80～120ml/min","Ccr 50～80ml/min","Ccr 10～20ml/min","Ccr＜10ml/min"],"a":2,"e":"内生肌酐清除率反映肾小球滤过功能，正常成人80～120ml/min；肾衰竭代偿期肾单位受损过半但尚能代偿，Ccr降至50～80ml/min。80～120ml/min为正常；50～20ml/min相当于失代偿期（氮质血症期）；10～20ml/min为肾衰竭期；Ccr＜10ml/min已进入尿毒症期"},{"q":"肾衰竭期","o":["Ccr 50～20ml/min","Ccr 80～120ml/min","Ccr 50～80ml/min","Ccr 10～20ml/min","Ccr＜10ml/min"],"a":3,"e":"Ccr降至10～20ml/min时肾小球滤过功能严重受损，代谢废物明显潴留，进入肾衰竭期。80～120ml/min为正常；50～80ml/min为肾功能不全代偿期；50～20ml/min为失代偿期；Ccr＜10ml/min则为尿毒症期，需肾脏替代治疗，此期对利尿剂反应极差"},{"q":"大叶性肺炎表现为","o":["肺泡呼吸音减弱","管样呼吸音","发作性呼吸困难，咳大量粉红色泡沫痰","Cheyne-Stokes呼吸","Kussmaul呼吸"],"a":1,"e":"大叶性肺炎实变期肺组织致密，支气管呼吸音经实变肺组织传导至体表增强，在正常肺泡呼吸音区听到支气管呼吸音，称管样呼吸音，伴浊音及病侧语音共振增强。肺泡呼吸音减弱见于气胸、胸腔积液、肺气肿；粉红色泡沫痰为急性肺水肿；Cheyne-Stokes呼吸与Kussmaul呼吸均为呼吸节律异常，非实变体征"},{"q":"慢性阻塞性肺气肿表现为","o":["肺泡呼吸音减弱","管样呼吸音","发作性呼吸困难，咳大量粉红色泡沫痰","Cheyne-Stokes呼吸","Kussmaul呼吸"],"a":0,"e":"慢性阻塞性肺气肿肺泡壁破坏、含气量增多而通气量减少，呼吸音传导障碍，听诊双肺肺泡呼吸音减弱，伴呼气延长与过清音。管样呼吸音为肺实变的体征，见于大叶性肺炎；大量粉红色泡沫痰见于急性肺水肿；Cheyne-Stokes呼吸为周期性呼吸暂停，见于心衰、脑病；Kussmaul呼吸为深大呼吸，见于酸中毒"},{"q":"上述疾病最可能出现水冲脉的是","o":["甲状腺功能亢进症","单纯性甲状腺肿","甲状腺癌","慢性淋巴性甲状腺炎","亚急性甲状腺炎"],"a":0,"e":"甲状腺功能亢进症因代谢亢进、外周血管扩张、脉压增大，出现脉搏骤起骤落的水冲脉，伴心悸、多汗、突眼及甲状腺血管杂音。单纯性甲状腺肿仅有甲状腺肿大而无甲亢症状；甲状腺癌以结节为主；慢性淋巴细胞性甲状腺炎与亚急性甲状腺炎主要表现为甲状腺质地改变或疼痛，均无水冲脉"},{"q":"上述疾病中常伴甲状腺触痛的是","o":["甲状腺功能亢进症","单纯性甲状腺肿","甲状腺癌","慢性淋巴性甲状腺炎","亚急性甲状腺炎"],"a":4,"e":"亚急性甲状腺炎多继发于病毒感染，甲状腺出现疼痛与触痛，质较硬，常伴发热及短暂甲状腺功能异常，活动期甲状腺球蛋白升高，炎症控制后迅速下降。甲亢为功能亢进无触痛；单纯性甲状腺肿为弥漫性肿大无疼痛；甲状腺癌表现为无痛性结节；慢性淋巴细胞性甲状腺炎质韧、一般无明显触痛"},{"q":"急性细菌性痢疾时可见","o":["便后滴血","柏油便","洗肉水样便","果酱样脓血便","黏液脓血便"],"a":4,"e":"急性细菌性痢疾由志贺菌感染结肠黏膜，形成炎症、坏死与溃疡，排出黏液脓血便，常伴腹痛、里急后重，镜检以中性粒细胞为主、红细胞少于白细胞。便后滴血见于痔、肛裂或直肠息肉；柏油便为上消化道出血；洗肉水样便见于急性出血性坏死性肠炎；果酱样脓血便为阿米巴痢疾"},{"q":"阿米巴痢疾时可见","o":["便后滴血","柏油便","洗肉水样便","果酱样脓血便","黏液脓血便"],"a":3,"e":"阿米巴痢疾由溶组织内阿米巴侵袭肠黏膜，形成烧瓶状溃疡，粪便呈暗红色或果酱样脓血便，具肝腥味，镜检可见大量堆积变性红细胞且多于白细胞，嗜酸性粒细胞增多。黏液脓血便多见于细菌性痢疾；便后滴血见于痔、肛裂；柏油便提示上消化道出血；洗肉水样便见于出血性坏死性肠炎"},{"q":"哪种情况气管偏向患侧","o":["一侧气胸","一侧肺不张","双侧胸腔积液","双肺弥漫纤维化","右侧肺门1cm占位"],"a":1,"e":"一侧肺不张时患侧肺容积缩小、胸腔内负压增大，气管与纵隔被牵拉移向患侧，伴病侧胸廓平坦、叩诊浊音及呼吸音减弱。一侧气胸与大量胸腔积液使患侧压力增高，将气管推向健侧；双侧胸腔积液或双肺弥漫纤维化多为双侧对称性改变，无明显气管偏移；肺门小占位不足以推移气管"},{"q":"哪种情况气管移向健侧","o":["一侧气胸","一侧肺不张","双侧胸腔积液","双肺弥漫纤维化","右侧肺门1cm占位"],"a":0,"e":"一侧气胸时胸膜腔积气使患侧胸内压升高，推挤气管与心脏移向健侧，叩诊病侧鼓音、呼吸音减弱或消失。一侧肺不张使患侧容积缩小，气管反而移向患侧；双侧胸腔积液为双侧病变无偏移；双肺弥漫纤维化不引起单侧推移；右侧肺门1cm占位体积有限，通常不造成明显气管移位"},{"q":"肝细胞损伤，细胞膜通透性增加时最明显的表现是","o":["白蛋白降低","γ-球蛋白升高","单胺氧化酶增高","ALT升高","AFP升高"],"a":3,"e":"ALT主要存在于肝细胞胞质中，肝细胞受损、膜通透性增加时大量释放入血，其漏出率远大于AST且半衰期较长，是反映肝细胞损伤最敏感的指标，急性病毒性肝炎可显著升高。白蛋白降低反映肝合成功能减退；γ-球蛋白升高多见于慢性肝病；单胺氧化酶增高与肝纤维化相关；AFP升高提示肝癌"},{"q":"原发性肝癌时最明显的表现是","o":["白蛋白降低","γ-球蛋白升高","单胺氧化酶增高","ALT升高","AFP升高"],"a":4,"e":"甲胎蛋白是肝癌的肿瘤标志物，血清AFP对原发性肝癌诊断阳性率约60%～80%，可用于疗效监测、复发随访及预后判断，持续显著升高最具意义。ALT升高主要反映肝细胞损伤；白蛋白降低提示合成功能下降；γ-球蛋白升高见于慢性肝病；单胺氧化酶增高与肝纤维化相关"},{"q":"帕金森病患者可能出现的步态是","o":["蹒跚步态","共济失调步态","慌张步态","剪刀步态","间隙性跛行"],"a":2,"e":"慌张步态表现为起步后小步急速趋行、双脚擦地、身体前倾且有难以止步之势，是帕金森病的特征性步态，与黑质多巴胺能神经元变性有关。蹒跚步态见于佝偻病或进行性肌营养不良；共济失调步态见于脊髓病变或小脑疾病；剪刀步态因双下肢肌张力增高，见于脑性瘫痪与截瘫；间歇性跛行见于动脉硬化"},{"q":"下肢动脉粥样硬化闭塞症可能出现的步态是","o":["蹒跚步态","共济失调步态","慌张步态","剪刀步态","间隙性跛行"],"a":4,"e":"间歇性跛行是行走中下肢突发酸痛乏力、被迫停步、休息后缓解的步态，因下肢动脉供血不足所致，见于动脉粥样硬化、高血压等。蹒跚步态见于肌营养不良或佝偻病；共济失调步态见于脊髓病变，闭目不能保持平衡；慌张步态为帕金森病特征；剪刀步态见于脑瘫与截瘫"},{"q":"血清中未结合胆红素显著增加，见于","o":["溶血性黄疸","肝细胞性黄疸","胆汁淤积性黄疸","Crigler-Najjar综合征","Rotor综合征"],"a":0,"e":"溶血时大量红细胞破坏，血清非结合胆红素显著增高，STB升高伴非结合胆红素明显增高即提示溶血性黄疸，CB/STB常＜20%，一般黄疸较轻。肝细胞性黄疸结合与非结合胆红素均增高；胆汁淤积性黄疸以结合胆红素升高为主、CB/STB＞50%；Crigler-Najjar与Rotor综合征属先天性胆红素代谢障碍，临床远较溶血少见"},{"q":"血清中结合胆红素与非结合胆红素均增加，见于","o":["溶血性黄疸","肝细胞性黄疸","胆汁淤积性黄疸","Crigler-Najjar综合征","Rotor综合征"],"a":0,"e":"官方答案为【溶血性黄疸】，但依据教材，正确答案为【肝细胞性黄疸】。肝细胞受损时摄取、结合与排泄胆红素均障碍，总胆红素增高且结合与非结合胆红素同时增加，是肝细胞性黄疸的特征，CB/STB多在20%～50%。溶血性黄疸仅非结合胆红素明显增高；胆汁淤积性黄疸以结合胆红素为主、比值＞50%；Crigler-Najjar与Rotor综合征为先天性胆红素代谢障碍"},{"q":"属于肾性少尿的病因是","o":["休克","急性肾小管坏死","肾血管狭窄","前列腺肥大","肾病综合征"],"a":1,"e":"急性肾小管坏死属肾性少尿，因肾小管上皮细胞损伤、坏死致肾小球滤过率下降，可由生物毒、重金属、化学毒或严重肾盂肾炎肾乳头坏死等引起，恢复期可出现多尿。休克致肾缺血属肾前性；肾血管狭窄为肾前性缺血因素；前列腺肥大压迫尿路属肾后性梗阻；肾病综合征以大量蛋白尿和水肿为主，非少尿主要病因"},{"q":"属于肾后性少尿的病因是","o":["休克","急性肾小管坏死","肾血管狭窄","前列腺肥大","肾病综合征"],"a":3,"e":"前列腺肥大压迫后尿道或膀胱出口，造成机械性尿路梗阻，使尿液排出受阻而致少尿，属肾后性因素，解除梗阻后肾功能多可改善。休克与肾血管狭窄导致肾缺血，属肾前性；急性肾小管坏死损伤肾小管本身，属肾性；肾病综合征虽有水肿与有效循环血量不足，但不属于尿路梗阻"},{"q":"青光眼患者头痛最常见的伴随症状是","o":["头痛伴剧烈呕吐","头痛伴有发热","头痛伴一侧肢体瘫痪","头痛伴脑膜刺激征","头痛伴视力障碍"],"a":4,"e":"青光眼因眼压升高导致头痛，同时损害视神经，出现视力下降、视野缺损等视力障碍，伴视力障碍是青光眼或脑肿瘤头痛的特点。伴剧烈呕吐多见于颅内高压；伴发热提示颅内或全身感染；一侧肢体瘫痪提示脑血管意外；脑膜刺激征见于脑膜炎或蛛网膜下腔出血"},{"q":"蛛网膜下腔出血最常见的伴随症状是","o":["头痛伴剧烈呕吐","头痛伴有发热","头痛伴一侧肢体瘫痪","头痛伴脑膜刺激征","头痛伴视力障碍"],"a":3,"e":"蛛网膜下腔出血时血液进入蛛网膜下腔刺激脑膜，出现剧烈头痛与颈项强直、克氏征阳性等脑膜刺激征，伴脑膜刺激征提示脑膜炎或蛛网膜下腔出血。伴视力障碍见于青光眼或脑肿瘤；伴发热多见于颅内感染；一侧肢体瘫痪提示脑实质血管病变；剧烈呕吐虽可伴发，但定位价值不及脑膜刺激征"}];
